17	/*
18	 * tool_emotion_audio.c — play_audio and stop_audio via nxplayer C API.
19	 *
20	 * play_audio:  Parse audio_id (1-14), look up filename, read WAV header,
21	 *              create nxplayer context, set device to "pcm0",
22	 *              call nxplayer_playraw() with explicit params.
23	 *              Playback is asynchronous; the nxplayer context is reference-
24	 *              counted and self-frees when playback completes.
25	 *
26	 * stop_audio:  Stop current playback via nxplayer_stop() and release the
27	 *              reference via nxplayer_release().
28	 */
