78	/* ── Player context (mutex protected — TR-002) ────────────────────── */
79	
80	static pthread_mutex_t    s_audio_mtx = PTHREAD_MUTEX_INITIALIZER;
81	static struct nxplayer_s *s_player    = NULL;
82	static int                s_current_id = 0;
83	
84	/* ── WAV header reader ──────────────────────────────────────────────── */
85	/* Reads a WAV file header and returns sample_rate, channels, bits.
86	 * Returns 0 on success, -1 on error.  Caller owns nothing. */
87	
88	struct wav_params {
89	    uint32_t sample_rate;
90	    uint16_t channels;
91	    uint16_t bits;
92	    uint32_t data_offset;
93	    uint32_t data_size;
94	};
95	
96	static int wav_read_header(const char *path, struct wav_params *wp)
97	{
98	    unsigned char hdr[44];
99	    int fd = open(path, O_RDONLY);
100	    if (fd < 0) return -1;
101	    if (read(fd, hdr, 44) != 44) { close(fd); return -1; }
102	    close(fd);
103	
104	    if (memcmp(hdr, "RIFF", 4) || memcmp(hdr + 8, "WAVE", 4))
105	        return -1;
106	
107	    wp->channels    = hdr[22] | (hdr[23] << 8);
108	    wp->sample_rate = hdr[24] | (hdr[25] << 8) | (hdr[26] << 16) | (hdr[27] << 24);
109	    wp->bits        = hdr[34] | (hdr[35] << 8);
110	
111	    /* Find "data" chunk */
112	    uint32_t off = 36;
113	    while (off < 44) {
114	        if (memcmp(hdr + off, "data", 4) == 0) {
115	            wp->data_offset = off + 8;
116	            wp->data_size   = hdr[off+4] | (hdr[off+5] << 8)
117	                            | (hdr[off+6] << 16) | (hdr[off+7] << 24);
118	            return 0;
119	        }
120	        off += 8 + (hdr[off+4] | (hdr[off+5] << 8)
121	                  | (hdr[off+6] << 16) | (hdr[off+7] << 24));
122	    }
123	    /* No "data" chunk in first 44 bytes — use default offset */
124	    wp->data_offset = 44;
125	    /* Estimate data size from file total */
126	    struct stat st;
127	    if (stat(path, &st) == 0 && (uint32_t)st.st_size > 44)
128	        wp->data_size = (uint32_t)st.st_size - 44;
129	    else
130	        wp->data_size = 0;
131	    return 0;
132	}
