134	/* ── play_audio ────────────────────────────────────────────────────── */
135	
136	int tool_play_audio_execute(const char *input_json, char *output, size_t output_size)
137	{
138	    cJSON *root = cJSON_Parse(input_json);
139	    if (!root) {
140	        snprintf(output, output_size, "{\"error\":\"invalid json\"}");
141	        return ERROR;
142	    }
143	
144	    cJSON *audio_id = cJSON_GetObjectItem(root, "audio_id");
145	    int id = 0;
146	    if (cJSON_IsNumber(audio_id)) {
147	        id = audio_id->valueint;
148	    } else if (cJSON_IsString(audio_id)) {
149	        /* LLM may pass numeric strings with stray quotes like "\"4\"" */
150	        const char *raw = audio_id->valuestring;
151	        char clean[16];
152	        size_t j = 0;
153	        for (size_t i = 0; raw[i] && j < sizeof(clean) - 1; i++) {
154	            if (raw[i] >= '0' && raw[i] <= '9')
155	                clean[j++] = raw[i];
156	        }
157	        clean[j] = '\0';
158	        id = j > 0 ? atoi(clean) : 0;
159	    } else {
160	        snprintf(output, output_size, "{\"error\":\"audio_id required\"}");
161	        cJSON_Delete(root);
162	        return ERROR;
163	    }
164	
165	    if (id < 1 || id > (int)AUDIO_MAP_SIZE) {
166	        snprintf(output, output_size,
167	            "{\"error\":\"audio_id out of range (1-%d)\"}", (int)AUDIO_MAP_SIZE);
168	        cJSON_Delete(root);
169	        return ERROR;
170	    }
171	
172	    cJSON *loop_j = cJSON_GetObjectItem(root, "loop");
173	    bool loop = cJSON_IsBool(loop_j) ? cJSON_IsTrue(loop_j) : false;
174	
175	    cJSON_Delete(root);
176	
177	    const char *fname = s_audio_map[id - 1].filename;
178	    const char *label = s_audio_map[id - 1].label_cn;
179	    char filepath[128];
180	    snprintf(filepath, sizeof(filepath), AUDIO_DIR "/%s", fname);
181	
182	    /* Mutex-protected playback state update (TR-002) */
183	    pthread_mutex_lock(&s_audio_mtx);
184	
185	    /* Stop previous playback if active */
186	    if (s_player) {
187	        syslog(LOG_INFO, "[emotion] stopping previous audio %d for new %d\n",
188	               s_current_id, id);
189	        nxplayer_stop(s_player);
190	        nxplayer_release(s_player);
191	        s_player    = NULL;
192	        s_current_id = 0;
193	    }
194	
195	    /* Create nxplayer context */
196	    s_player = nxplayer_create();
197	    if (!s_player) {
198	        pthread_mutex_unlock(&s_audio_mtx);
199	        syslog(LOG_ERR, "[emotion] nxplayer_create failed\n");
200	        snprintf(output, output_size,
201	            "{\"status\":\"error\",\"reason\":\"player init failed\"}");
202	        return ERROR;
203	    }
204	
205	    /* Read WAV header for correct params — avoid nxplayer_playfile
206	     * auto-detect bug (double-speed / distortion on NuttX audio). */
207	    struct wav_params wp;
208	    if (wav_read_header(filepath, &wp) != 0) {
209	        syslog(LOG_ERR, "[emotion] bad WAV header: %s\n", filepath);
210	        nxplayer_release(s_player);
211	        s_player = NULL;
212	        pthread_mutex_unlock(&s_audio_mtx);
213	        snprintf(output, output_size,
214	            "{\"status\":\"error\",\"reason\":\"bad wav header\"}");
215	        return ERROR;
216	    }
217	
218	    nxplayer_setdevice(s_player, "/dev/audio/pcm0");
219	    int ret = nxplayer_playraw(s_player, filepath, AUDIO_FMT_PCM, 0,
220	        wp.channels, wp.bits, wp.sample_rate, 0);
221	    if (ret != OK) {
222	        syslog(LOG_ERR, "[emotion] playfile %s failed: ret=%d\n", filepath, ret);
223	        nxplayer_release(s_player);
224	        s_player = NULL;
225	        pthread_mutex_unlock(&s_audio_mtx);
226	        snprintf(output, output_size,
227	            "{\"status\":\"error\",\"reason\":\"playback failed\"}");
228	        return ERROR;
229	    }
230	
231	    s_current_id = id;
232	    pthread_mutex_unlock(&s_audio_mtx);
233	
234	    syslog(LOG_INFO, "[emotion] play_audio: id=%d file=%s label=%s loop=%d\n",
235	           id, fname, label, loop);
236	
237	    snprintf(output, output_size,
238	        "{\"status\":\"playing\",\"audio_id\":%d,\"label\":\"%s\",\"loop\":%s}",
239	        id, label, loop ? "true" : "false");
240	    return OK;
241	}
