243	/* ── stop_audio ────────────────────────────────────────────────────── */
244	
245	int tool_stop_audio_execute(const char *input_json, char *output, size_t output_size)
246	{
247	    (void)input_json;
248	
249	    pthread_mutex_lock(&s_audio_mtx);
250	
251	    int  stopped_id  = s_current_id;
252	    bool was_playing = (s_player != NULL);
253	
254	    if (s_player) {
255	        syslog(LOG_INFO, "[emotion] stopping audio id=%d\n", stopped_id);
256	        nxplayer_stop(s_player);
257	        nxplayer_release(s_player);
258	        s_player     = NULL;
259	        s_current_id = 0;
260	    }
261	
262	    pthread_mutex_unlock(&s_audio_mtx);
263	
264	    if (was_playing) {
265	        snprintf(output, output_size,
266	            "{\"status\":\"stopped\",\"audio_id\":%d,\"stop_reason\":\"user_request\"}",
267	            stopped_id);
268	    } else {
269	        snprintf(output, output_size,
270	            "{\"status\":\"not_playing\",\"stop_reason\":\"no_active_playback\"}");
271	    }
272	    return OK;
273	}
274	
275	/* ── Direct stop (no JSON parsing) — for voice_channel before TTS ─── */
276	
277	void tool_emotion_audio_stop(void)
278	{
279	    pthread_mutex_lock(&s_audio_mtx);
280	
281	    if (s_player) {
282	        syslog(LOG_INFO, "[emotion] TTS preempt: stopping audio id=%d\n",
283	               s_current_id);
284	        nxplayer_stop(s_player);
285	        nxplayer_release(s_player);
286	        s_player     = NULL;
287	        s_current_id = 0;
288	    }
289	
290	    pthread_mutex_unlock(&s_audio_mtx);
291	}
292	
293	bool tool_emotion_audio_is_playing(void)
294	{
295	    bool playing;
296	    pthread_mutex_lock(&s_audio_mtx);
297	    /* s_player stays allocated after playback ends (for reuse / stop);
298	     * only treat as "playing" while the nxplayer state is active. */
299	    playing = (s_player != NULL && s_player->state != 0);
300	    if (!playing && s_player != NULL) {
301	        /* Playback finished — release so mic capture can resume */
302	        nxplayer_release(s_player);
303	        s_player     = NULL;
304	        s_current_id = 0;
305	    }
306	    pthread_mutex_unlock(&s_audio_mtx);
307	    return playing;
308	}
