310	/* ── Synchronous play (blocks until the WAV finishes) ──────────────── */
311	/* For proactive prompt sequences (e.g. charging feedback) that play a
312	 * short preset first and TTS afterwards: returns only after playback
313	 * completed, so callers can sequence audio→TTS deterministically on
314	 * pcm0.  Must run on a worker thread (blocks for the WAV duration). */
315	
316	int tool_emotion_audio_play_wait(int audio_id)
317	{
318	    if (audio_id < 1 || audio_id > (int)AUDIO_MAP_SIZE) {
319	        return -EINVAL;
320	    }
321	
322	    const char *fname = s_audio_map[audio_id - 1].filename;
323	    char filepath[128];
324	    snprintf(filepath, sizeof(filepath), AUDIO_DIR "/%s", fname);
325	
326	    /* Stop previous emotion audio so pcm0 is free */
327	    tool_emotion_audio_stop();
328	
329	    struct wav_params wp;
330	    if (wav_read_header(filepath, &wp) != 0) {
331	        syslog(LOG_ERR, "[emotion] play_wait bad WAV header: %s\n", filepath);
332	        return -EIO;
333	    }
334	
335	    struct nxplayer_s *pl = nxplayer_create();
336	    if (!pl) {
337	        syslog(LOG_ERR, "[emotion] play_wait nxplayer_create failed\n");
338	        return -ENOMEM;
339	    }
340	    nxplayer_setdevice(pl, "/dev/audio/pcm0");
341	
342	    int ret = nxplayer_playraw(pl, filepath, AUDIO_FMT_PCM, 0,
343	                               wp.channels, wp.bits, wp.sample_rate, 0);
344	    if (ret != OK) {
345	        syslog(LOG_ERR, "[emotion] play_wait %s failed: ret=%d\n",
346	               filepath, ret);
347	        nxplayer_release(pl);
348	        return -EIO;
349	    }
350	
351	    /* Same IDLE→PLAYING→IDLE wait as alert_play_worker: playraw returns
352	     * before the internal play thread sets state=PLAYING, so first wait
353	     * for the transition, then for playback to finish. */
354	    int waited_ms = 0;
355	    while (waited_ms < 3000 && pl->state == 0) {
356	        usleep(50 * 1000);
357	        waited_ms += 50;
358	    }
359	    while (pl->state != 0 && waited_ms < 15000) {
360	        usleep(200 * 1000);
361	        waited_ms += 200;
362	    }
363	
364	    nxplayer_stop(pl);
365	    nxplayer_release(pl);
366	
367	    syslog(LOG_INFO, "[emotion] play_wait: id=%d file=%s finished (%dms)\n",
368	           audio_id, fname, waited_ms);
369	    return 0;
370	}
