372	/* ── System alert audio (highest priority) ──────────────────────────── */
373	
374	#include "voice/voice_channel.h"
375	
376	/* De-dup: track last played alert to prevent spam */
377	static int   s_last_alert_id  = -1;
378	static time_t s_last_alert_ts = 0;
379	#define ALERT_COOLDOWN_SEC 30  /* no repeat within 30s */
380	
381	/**
382	 * Play a system alert audio at highest priority.
383	 * - Async: playback runs on a detached worker thread so callers on the
384	 *   LVGL thread (launcher timer, battery timer) never block
385	 * - Stops any active TTS (voice_channel_interrupt_tts)
386	 * - Stops any emotion audio
387	 * - Plays the WAV file via nxplayer
388	 * - De-duplicates: same alert_id won't replay within cooldown
389	 *
390	 * @param alert_id  Audio ID (15=low_battery, 16=no_network, 17=wifi_timeout)
391	 * @param force     If true, bypass de-dup (e.g. user explicitly requests)
392	 */
393	
394	/* One alert at a time: a new alert arriving while one is playing is
395	 * dropped (the 30s cooldown makes this rare). */
396	static volatile bool s_alert_playing = false;
397	
398	static void* alert_play_worker(void* arg)
399	{
400	    int alert_id = (int)(intptr_t)arg;
401	
402	    const char *fname = s_audio_map[alert_id - 1].filename;
403	    char filepath[128];
404	    snprintf(filepath, sizeof(filepath), AUDIO_DIR "/%s", fname);
405	
406	    /* Stop emotion audio first */
407	    tool_emotion_audio_stop();
408	
409	    /* Interrupt active TTS so alert takes the speaker immediately */
410	    voice_channel_interrupt_tts();
411	
412	    /* Small gap: let previous audio device release */
413	    usleep(100 * 1000);
414	
415	    /* Read WAV header for correct params — same fix as TTS */
416	    struct wav_params wp;
417	    if (wav_read_header(filepath, &wp) != 0) {
418	        syslog(LOG_ERR, "[emotion] alert bad WAV header: %s\n", filepath);
419	        s_alert_playing = false;
420	        return NULL;
421	    }
422	    syslog(LOG_INFO, "[emotion] alert wav: %s = %uch %luHz %ubit\n",
423	           fname, wp.channels, (unsigned long)wp.sample_rate, wp.bits);
424	
425	    /* Play alert via dedicated nxplayer */
426	    struct nxplayer_s *ap = nxplayer_create();
427	    if (!ap) {
428	        syslog(LOG_ERR, "[emotion] alert nxplayer_create failed\n");
429	        s_alert_playing = false;
430	        return NULL;
431	    }
432	    nxplayer_setdevice(ap, "/dev/audio/pcm0");
433	
434	    int ret = nxplayer_playraw(ap, filepath, AUDIO_FMT_PCM, 0,
435	        wp.channels, wp.bits, wp.sample_rate, 0);
436	    if (ret != OK) {
437	        syslog(LOG_ERR, "[emotion] alert playraw %s failed: ret=%d\n",
438	            filepath, ret);
439	        nxplayer_release(ap);
440	        s_alert_playing = false;
441	        return NULL;
442	    }
443	
444	    /* Wait for playback completion.  nxplayer_playraw returns before the
445	     * internal play thread sets state=PLAYING(1) — state is still IDLE(0)
446	     * at first check, so first wait for the IDLE→PLAYING transition, then
447	     * for the return to IDLE (playback finished). */
448	    int waited_ms = 0;
449	    #define ALERT_MAX_WAIT_MS   15000
450	    #define ALERT_START_WAIT_MS 3000
451	    while (waited_ms < ALERT_START_WAIT_MS && ap->state == 0) {
452	        usleep(50 * 1000);
453	        waited_ms += 50;
454	    }
455	    while (ap->state != 0 && waited_ms < ALERT_MAX_WAIT_MS) {
456	        usleep(200 * 1000);
457	        waited_ms += 200;
458	    }
459	
460	    nxplayer_stop(ap);
461	    nxplayer_release(ap);
462	
463	    syslog(LOG_INFO, "[emotion] alert %d finished (%dms)\n",
464	        alert_id, waited_ms);
465	    s_alert_playing = false;
466	    return NULL;
467	}
468	
469	void tool_system_alert_play(int alert_id, int force)
470	{
471	    if (alert_id < 15 || alert_id > 17) return;
472	
473	    /* De-dup: skip if same alert played recently */
474	    if (!force && alert_id == s_last_alert_id
475	        && time(NULL) - s_last_alert_ts < ALERT_COOLDOWN_SEC) {
476	        syslog(LOG_INFO, "[emotion] alert %d suppressed (cooldown=%lds)\n",
477	               alert_id, (long)(time(NULL) - s_last_alert_ts));
478	        return;
479	    }
480	
481	    if (s_alert_playing) {
482	        syslog(LOG_INFO, "[emotion] alert %d skipped (another alert playing)\n",
483	               alert_id);
484	        return;
485	    }
486	
487	    s_last_alert_id  = alert_id;
488	    s_last_alert_ts  = time(NULL);
489	    s_alert_playing  = true;
490	
491	    syslog(LOG_INFO, "[emotion] system alert: id=%d label=%s file=%s\n",
492	           alert_id, s_audio_map[alert_id - 1].label_cn,
493	           s_audio_map[alert_id - 1].filename);
494	
495	    pthread_t tid;
496	    pthread_attr_t attr;
497	    pthread_attr_init(&attr);
498	    pthread_attr_setstacksize(&attr, 16 * 1024);
499	    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
500	    if (pthread_create(&tid, &attr, alert_play_worker,
501	                       (void*)(intptr_t)alert_id) != 0) {
502	        syslog(LOG_ERR, "[emotion] alert worker spawn failed\n");
503	        s_alert_playing = false;
504	    }
505	}
