1898	int voice_channel_speak(const char* text)
1899	{
1900	    syslog(LOG_INFO, "[%s] speak\n", TAG);
1901	    if (!text || text[0] == '\0') {
1902	        syslog(LOG_ERR, "[%s] speak: empty/null text\n", TAG);
1903	        /* Must still transition PROCESSING→LISTENING, otherwise
1904	         * conversation_thread waits forever. */
1905	        if (s_voice.state == VOICE_PROCESSING) {
1906	            s_voice.state = VOICE_LISTENING;
1907	        }
1908	        return -EINVAL;
1909	    }
1910	
1911	    /* If a preset audio is already playing, don't interrupt it with TTS.
1912	     * Audio and TTS share /dev/audio/pcm0 — audio takes priority.
1913	     * Check BEFORE acquiring any voice lock to avoid deadlock. */
1914	#ifdef CONFIG_AI_AGENT_EMOTION_TOY
1915	    if (tool_emotion_audio_is_playing()) {
