46	/* ---------------------------------------------------------------
47	 * System-prompt cache
48	 *
49	 * Building the prompt is expensive on this platform: it opens
50	 * AGENT_USER_FILE, AGENT_MEMORY_FILE, today's daily-note file, and
51	 * (twice) scans AGENT_SKILLS_DIR.  That is 20+ filesystem calls per
52	 * message which the FAT-on-SPI-flash driver services one at a time.
53	 *
54	 * We cache the fully-built prompt and reuse it whenever nothing that
55	 * would affect its content has changed:
56	 *   • skills-directory hash                    (skill_loader_get_hash)
57	 *   • mtime of USER.md, MEMORY.md, today's daily note
58	 *   • the current wall-clock minute (time_str is minute-precision
59	 *     for cache purposes; sub-minute callers get the same string,
60	 *     which is fine — the LLM uses the get_current_time tool for
61	 *     anything needing seconds).
62	 *
63	 * Cache lives in .bss (≤10 KB).  Zero heap allocation on the hot
64	 * path when the cache hits.
65	 * ------------------------------------------------------------- */
66	#define CTX_CACHE_MAX_LEN (AGENT_CONTEXT_BUF_SIZE)
67	
68	/* Lazily malloc'd on first cache store, so the 8KB cache lives in the
69	 * PSRAM heap instead of internal DRAM .bss (DRAM is scarce on ESP32-S3). */
70	static char       *s_cache_buf         = NULL;
71	static size_t      s_cache_len         = 0;
72	static unsigned    s_cache_skills_hash = 0;
73	static time_t      s_cache_user_mtime  = 0;
74	static time_t      s_cache_mem_mtime   = 0;
75	static time_t      s_cache_daily_mtime = 0;
76	static time_t      s_cache_minute      = 0;
77	
78	/* mtime of a file, or 0 if unavailable */
79	static time_t file_mtime(const char *path)
80	{
81	    struct stat st;
82	    return (stat(path, &st) == 0) ? st.st_mtime : 0;
83	}
