103	/* Append a file's content under a "## header", but never write more
104	 * than max_bytes bytes of body. Truncated output ends with a marker. */
105	static size_t append_file_capped(char *buf, size_t size, size_t offset,
106	                                 const char *path, const char *header,
107	                                 size_t max_bytes)
108	{
109	    FILE *f = fopen(path, "r");
110	    if (!f) return offset;
111	
112	    if (header && offset < size - 1) {
113	        offset += snprintf(buf + offset, size - offset, "\n## %s\n\n", header);
114	    }
115	
116	    size_t avail = (size > offset + 1) ? (size - offset - 1) : 0;
117	    if (avail > max_bytes) avail = max_bytes;
118	
119	    size_t n = fread(buf + offset, 1, avail, f);
120	    offset += n;
121	    buf[offset] = '\0';
122	
123	    /* If file still has more, mark truncation. */
124	    if (n == avail && fgetc(f) != EOF && offset < size - 32) {
125	        offset += snprintf(buf + offset, size - offset, "\n...(截断)\n");
126	    }
127	    fclose(f);
128	    return offset;
129	}
