304	int context_build_messages(const char *history_json, const char *user_message,
305	                                  char *buf, size_t size)
306	{
307	    cJSON *history = cJSON_Parse(history_json);
308	    if (!history) {
309	        history = cJSON_CreateArray();
310	    }
311	
312	    cJSON *user_msg = cJSON_CreateObject();
313	    cJSON_AddStringToObject(user_msg, "role", "user");
314	    cJSON_AddStringToObject(user_msg, "content", user_message);
315	    cJSON_AddItemToArray(history, user_msg);
316	
317	    char *json_str = cJSON_PrintUnformatted(history);
318	    cJSON_Delete(history);
319	
320	    if (json_str) {
321	        strncpy(buf, json_str, size - 1);
322	        buf[size - 1] = '\0';
323	        free(json_str);
324	    } else {
325	        /* Fallback (cJSON_PrintUnformatted above returned NULL, e.g. OOM).
326	         * Do NOT hand-roll JSON with %s — an unescaped quote/backslash in
327	         * user_message would emit invalid JSON.  Rebuild via cJSON so the
328	         * content stays escaped; if that also fails, yield an empty array. */
329	        cJSON *fb_arr = cJSON_CreateArray();
330	        cJSON *fb_msg = cJSON_CreateObject();
331	        cJSON_AddStringToObject(fb_msg, "role", "user");
332	        cJSON_AddStringToObject(fb_msg, "content", user_message);
333	        cJSON_AddItemToArray(fb_arr, fb_msg);
334	        char *fb_str = cJSON_PrintUnformatted(fb_arr);
335	        cJSON_Delete(fb_arr);
336	        if (fb_str) {
337	            strncpy(buf, fb_str, size - 1);
338	            buf[size - 1] = '\0';
339	            free(fb_str);
340	        } else {
341	            snprintf(buf, size, "[]");
342	        }
343	    }
344	
345	    return OK;
346	}
