2388	 * Name: nxplayer_playraw
2389	 *
2390	 *   nxplayer_playraw() tries to play the audio file using the Audio
2391	 *   system.  If a preferred device is specified, it will try to use that
2392	 *   device otherwise it will perform a search of the Audio device files
2393	 *   to find a suitable device.
2394	 *
2395	 * Input:
2396	 *   pplayer    Pointer to the initialized MPlayer context
2397	 *   pfilename  Pointer to the filename to play
2398	 *   filefmt   - Format of audio in filename if known, AUDIO_FMT_UNDEF
2399	 *               to let nxplayer_playraw() determine automatically.
2400	 *   subfmt    - Sub-Format of audio in filename if known, AUDIO_FMT_UNDEF
2401	 *               to let nxplayer_playraw() determine automatically.
2402	 *   nchannels  channel num
2403	 *   bpsampe    bit width
2404	 *   samprate   sample rate
2405	 *   chmap      channel map
2406	 *
2407	 * Returns:
2408	 *   OK         File is being played
2409	 *   -EBUSY     The media device is busy
2410	 *   -ENOSYS    The media file is an unsupported type
2411	 *   -ENODEV    No audio device suitable to play the media type
2412	 *   -ENOENT    The media file was not found
2413	 *
2414	 ****************************************************************************/
2415	
2416	int nxplayer_playraw(FAR struct nxplayer_s *pplayer,
2417	                     FAR const char *pfilename,
2418	                     int filefmt, int subfmt, uint8_t nchannels,
2419	                     uint8_t bpsamp, uint32_t samprate, uint8_t chmap)
2420	{
2421	#ifdef CONFIG_NXPLAYER_INCLUDE_MEDIADIR
2422	  char path[PATH_MAX];
2423	#endif
2424	  int  tmpsubfmt = AUDIO_FMT_UNDEF;
2425	  int  ret;
2426	  int  c;
2427	
2428	  DEBUGASSERT(pplayer != NULL);
2429	  DEBUGASSERT(pfilename != NULL);
2430	
2431	  if (pplayer->state != NXPLAYER_STATE_IDLE)
2432	    {
2433	      return -EBUSY;
2434	    }
2435	
2436	  /* Test that the specified file exists */
2437	
2438	#ifdef CONFIG_NXPLAYER_HTTP_STREAMING_SUPPORT
2439	  if ((pplayer->fd = _open_with_http(pfilename)) == -1)
2440	#else
2441	  if ((pplayer->fd = open(pfilename, O_RDONLY)) == -1)
2442	#endif
2443	    {
2444	      /* File not found.  Test if its in the mediadir */
2445	
2446	#ifdef CONFIG_NXPLAYER_INCLUDE_MEDIADIR
2447	      snprintf(path, sizeof(path), "%s/%s", pplayer->mediadir, pfilename);
2448	
2449	      if ((pplayer->fd = open(path, O_RDONLY)) == -1)
2450	        {
2451	#ifdef CONFIG_NXPLAYER_MEDIA_SEARCH
2452	          /* File not found in the media dir.  Do a search */
2453	
