46	/* ── Tools format conversion ──────────────────────────────── */
47	
48	cJSON* build_openai_tools_array(const char* tools_json)
49	{
50	    if (!tools_json) {
51	        return NULL;
52	    }
53	
54	    cJSON* tools_spec = cJSON_Parse(tools_json);
55	
56	    if (!tools_spec || !cJSON_IsArray(tools_spec)) {
57	        cJSON_Delete(tools_spec);
58	        return NULL;
59	    }
60	
61	    cJSON* tools_arr = cJSON_CreateArray();
62	    cJSON* tool_def;
63	
64	    cJSON_ArrayForEach(tool_def, tools_spec)
65	    {
66	        cJSON* wrapper = cJSON_CreateObject();
67	
68	        cJSON_AddStringToObject(wrapper, "type", "function");
69	
70	        cJSON* func = cJSON_CreateObject();
71	        cJSON* name = cJSON_GetObjectItem(tool_def, "name");
72	        cJSON* desc = cJSON_GetObjectItem(tool_def, "description");
73	        cJSON* schema = cJSON_GetObjectItem(tool_def, "input_schema");
74	
75	        if (name && cJSON_IsString(name)) {
76	            cJSON_AddStringToObject(func, "name", name->valuestring);
77	        }
78	        if (desc && cJSON_IsString(desc)) {
79	            cJSON_AddStringToObject(func, "description",
80	                desc->valuestring);
81	        }
82	        if (schema) {
83	            cJSON_AddItemToObject(func, "parameters",
84	                cJSON_Duplicate(schema, 1));
85	        } else {
86	            cJSON* empty = cJSON_CreateObject();
87	            cJSON_AddStringToObject(empty, "type", "object");
88	            cJSON_AddItemToObject(empty, "properties",
89	                cJSON_CreateObject());
90	            cJSON_AddItemToObject(func, "parameters", empty);
91	        }
92	
93	        cJSON_AddItemToObject(wrapper, "function", func);
94	        cJSON_AddItemToArray(tools_arr, wrapper);
95	    }
96	
97	    cJSON_Delete(tools_spec);
98	    return tools_arr;
99	}
