103	/* Parse Format 1: <tool_call> <function=NAME> <parameter=KEY>VAL
104	 * </parameter> </function> </tool_call> */
105	void parse_xml_tool_calls(llm_response_t* resp)
106	{
107	    if (resp->call_count > 0 || !resp->text) {
108	        return;
109	    }
110	    if (!strstr(resp->text, "<tool_call>")) {
111	        return;
112	    }
113	
114	    const char* p = resp->text;
115	
116	    while (resp->call_count < AGENT_MAX_TOOL_CALLS) {
117	        const char* tc_start = strstr(p, "<tool_call>");
118	        const char* tc_end = strstr(p, "</tool_call>");
119	
120	        if (!tc_start || !tc_end || tc_end <= tc_start) {
121	            break;
122	        }
123	
124	        const char* fn_start = strstr(tc_start, "<function=");
125	        const char* fn_close = fn_start
126	            ? strchr(fn_start + 10, '>')
127	            : NULL;
128	
129	        if (!fn_start || !fn_close || fn_start > tc_end) {
130	            p = tc_end + 12;
131	            continue;
132	        }
133	
134	        llm_tool_call_t* call = &resp->calls[resp->call_count];
135	        size_t name_len = (size_t)(fn_close - (fn_start + 10));
136	
137	        if (name_len >= sizeof(call->name)) {
138	            name_len = sizeof(call->name) - 1;
139	        }
140	        memcpy(call->name, fn_start + 10, name_len);
141	        call->name[name_len] = '\0';
142	        snprintf(call->id, sizeof(call->id), "xml_%d",
143	            resp->call_count);
144	
145	        cJSON* args = cJSON_CreateObject();
146	        const char* pp = fn_close + 1;
147	
148	        while (pp < tc_end) {
149	            const char* ps = strstr(pp, "<parameter=");
150	
151	            if (!ps || ps >= tc_end) {
152	                break;
153	            }
154	            const char* ke = strchr(ps + 11, '>');
155	
156	            if (!ke || ke >= tc_end) {
157	                break;
158	            }
159	
160	            char key[64];
161	            size_t klen = (size_t)(ke - (ps + 11));
162	
163	            if (klen >= sizeof(key)) {
164	                klen = sizeof(key) - 1;
165	            }
166	            memcpy(key, ps + 11, klen);
167	            key[klen] = '\0';
168	
169	            const char* vs = ke + 1;
170	            const char* ve = strstr(vs, "</parameter>");
171	
172	            if (!ve || ve > tc_end) {
173	                break;
174	            }
175	
176	            size_t vlen = (size_t)(ve - vs);
177	            char* val = calloc(1, vlen + 1);
178	
179	            if (val) {
180	                memcpy(val, vs, vlen);
181	                cJSON_AddStringToObject(args, key, val);
182	                free(val);
183	            }
184	            pp = ve + 12;
185	        }
186	
187	        char* args_str = cJSON_PrintUnformatted(args);
188	
189	        cJSON_Delete(args);
190	        if (args_str) {
191	            call->input = args_str;
192	            call->input_len = strlen(args_str);
193	        }
194	
195	        resp->call_count++;
196	        p = tc_end + 12;
197	    }
198	
199	    if (resp->call_count > 0) {
200	        resp->tool_use = true;
201	        free(resp->text);
202	        resp->text = NULL;
203	        resp->text_len = 0;
204	        syslog(LOG_WARNING,
205	            "[%s] Parsed %d tool call(s) from XML fallback\n",
206	            TAG, resp->call_count);
207	    }
208	}
