210	/* Parse Format 2: <PREFIX:tool_call> <invoke name="NAME">
211	 * <parameter name="KEY">VAL</parameter> </invoke>
212	 * </PREFIX:tool_call> */
213	void parse_ns_xml_tool_calls(llm_response_t* resp)
214	{
215	    if (resp->call_count > 0 || !resp->text) {
216	        return;
217	    }
218	    if (!strstr(resp->text, ":tool_call>")) {
219	        return;
220	    }
221	
222	    const char* p = resp->text;
223	
224	    while (resp->call_count < AGENT_MAX_TOOL_CALLS) {
225	        const char* colon = strstr(p, ":tool_call>");
226	
227	        if (!colon) {
228	            break;
229	        }
230	
231	        const char* tc_start = colon;
232	
233	        while (tc_start > p && *(tc_start - 1) != '<') {
234	            tc_start--;
235	        }
236	        if (tc_start <= p || *(tc_start - 1) != '<') {
237	            break;
238	        }
239	        tc_start--;
240	
241	        size_t prefix_len = (size_t)(colon - (tc_start + 1));
242	
243	        if (prefix_len == 0 || prefix_len > 31) {
244	            p = colon + 11;
245	            continue;
246	        }
247	
248	        char prefix[32];
249	
250	        memcpy(prefix, tc_start + 1, prefix_len);
251	        prefix[prefix_len] = '\0';
252	
253	        char close_tag[64];
254	
255	        snprintf(close_tag, sizeof(close_tag),
256	            "</%s:tool_call>", prefix);
257	
258	        const char* tc_end = strstr(colon, close_tag);
259	
260	        if (!tc_end || tc_end <= tc_start) {
261	            p = colon + 11;
262	            continue;
263	        }
264	
265	        const char* inv = strstr(tc_start, "<invoke name=\"");
266	
267	        if (!inv || inv > tc_end) {
268	            p = tc_end + strlen(close_tag);
269	            continue;
270	        }
271	
272	        const char* ns = inv + 14;
273	        const char* ne = strchr(ns, '"');
274	
275	        if (!ne || ne > tc_end) {
276	            p = tc_end + strlen(close_tag);
277	            continue;
278	        }
279	
280	        llm_tool_call_t* call = &resp->calls[resp->call_count];
281	        size_t name_len = (size_t)(ne - ns);
282	
283	        if (name_len >= sizeof(call->name)) {
284	            name_len = sizeof(call->name) - 1;
285	        }
286	        memcpy(call->name, ns, name_len);
287	        call->name[name_len] = '\0';
288	        snprintf(call->id, sizeof(call->id), "nsxml_%d",
289	            resp->call_count);
290	
291	        cJSON* args = cJSON_CreateObject();
292	        const char* pp = ne;
293	
294	        while (pp < tc_end) {
295	            const char* ps = strstr(pp, "<parameter name=\"");
296	
297	            if (!ps || ps >= tc_end) {
298	                break;
299	            }
300	
301	            const char* ks = ps + 17;
302	            const char* ke = strchr(ks, '"');
303	
304	            if (!ke || ke >= tc_end) {
305	                break;
306	            }
307	
308	            const char* tc = strchr(ke, '>');
309	
310	            if (!tc || tc >= tc_end) {
311	                break;
312	            }
313	
314	            char key[64];
315	            size_t klen = (size_t)(ke - ks);
316	
317	            if (klen >= sizeof(key)) {
318	                klen = sizeof(key) - 1;
319	            }
320	            memcpy(key, ks, klen);
321	            key[klen] = '\0';
322	
323	            const char* vs = tc + 1;
324	            const char* ve = strstr(vs, "</parameter>");
325	
326	            if (!ve || ve > tc_end) {
327	                break;
328	            }
329	
330	            size_t vlen = (size_t)(ve - vs);
331	            char* val = calloc(1, vlen + 1);
332	
333	            if (val) {
334	                memcpy(val, vs, vlen);
335	                cJSON_AddStringToObject(args, key, val);
336	                free(val);
337	            }
338	            pp = ve + 12;
339	        }
340	
341	        char* args_str = cJSON_PrintUnformatted(args);
342	
343	        cJSON_Delete(args);
344	        if (args_str) {
345	            call->input = args_str;
346	            call->input_len = strlen(args_str);
347	        }
348	
349	        resp->call_count++;
350	        p = tc_end + strlen(close_tag);
351	    }
352	
353	    if (resp->call_count > 0) {
354	        resp->tool_use = true;
355	        free(resp->text);
356	        resp->text = NULL;
357	        resp->text_len = 0;
358	        syslog(LOG_WARNING,
359	            "[%s] Parsed %d tool call(s) from namespaced XML\n",
360	            TAG, resp->call_count);
361	    }
362	}
