364	/* ── Extract OpenAI tool_calls from response message ──────── */
365	
366	void extract_openai_tool_calls(cJSON* message, llm_response_t* resp)
367	{
368	    cJSON* text_content = cJSON_GetObjectItem(message, "content");
369	
370	    if (text_content && cJSON_IsString(text_content)
371	        && text_content->valuestring) {
372	        size_t tlen = strlen(text_content->valuestring);
373	
374	        resp->text = calloc(1, tlen + 1);
375	        if (resp->text) {
376	            memcpy(resp->text, text_content->valuestring, tlen);
377	            resp->text_len = tlen;
378	        }
379	    }
380	
381	    cJSON* rc = cJSON_GetObjectItem(message, "reasoning_content");
382	
383	    if (rc && cJSON_IsString(rc) && rc->valuestring
384	        && rc->valuestring[0]) {
385	        resp->reasoning_content = strdup(rc->valuestring);
386	    }
387	
388	    cJSON* tool_calls = cJSON_GetObjectItem(message, "tool_calls");
389	
390	    if (!tool_calls || !cJSON_IsArray(tool_calls)) {
391	        return;
392	    }
393	
394	    cJSON* tc;
395	
396	    cJSON_ArrayForEach(tc, tool_calls)
397	    {
398	        if (resp->call_count >= AGENT_MAX_TOOL_CALLS) {
399	            break;
400	        }
401	
402	        llm_tool_call_t* call = &resp->calls[resp->call_count];
403	        cJSON* id_item = cJSON_GetObjectItem(tc, "id");
404	
405	        if (id_item && cJSON_IsString(id_item)) {
406	            strncpy(call->id, id_item->valuestring,
407	                sizeof(call->id) - 1);
408	        }
409	
410	        cJSON* func_obj = cJSON_GetObjectItem(tc, "function");
411	
412	        if (func_obj) {
413	            cJSON* n = cJSON_GetObjectItem(func_obj, "name");
414	            cJSON* a = cJSON_GetObjectItem(func_obj, "arguments");
415	
416	            if (n && cJSON_IsString(n)) {
417	                strncpy(call->name, n->valuestring,
418	                    sizeof(call->name) - 1);
419	            }
420	            if (a && cJSON_IsString(a)) {
421	                size_t alen = strlen(a->valuestring);
422	
423	                call->input = calloc(1, alen + 1);
424	                if (call->input) {
425	                    memcpy(call->input, a->valuestring, alen);
426	                    call->input_len = alen;
427	                }
428	            }
429	        }
430	
431	        resp->call_count++;
432	    }
433	
434	    if (resp->call_count > 0) {
435	        resp->tool_use = true;
436	    }
437	}
