439	/* ── Response cleanup ─────────────────────────────────────── */
440	
441	void llm_response_free(llm_response_t* resp)
442	{
443	    free(resp->text);
444	    resp->text = NULL;
445	    resp->text_len = 0;
446	    free(resp->reasoning_content);
447	    resp->reasoning_content = NULL;
448	    for (int i = 0; i < resp->call_count; i++) {
449	        free(resp->calls[i].input);
450	        resp->calls[i].input = NULL;
451	    }
452	    resp->call_count = 0;
453	    resp->tool_use = false;
454	}
