=== model_name_for_api ===
 * Multi-provider gateways (e.g. OpenRouter) require the full
 * "provider/model" string, while single-vendor APIs expect only
 * the bare model name after the slash.
 */
const char* model_name_for_api(const char* model, const char* host)
{
    /* Multi-provider gateways need the full identifier */
    if (strstr(host, "openrouter.ai")) {
        return model;
    }

    const char* slash = strchr(model, '/');
    return slash ? slash + 1 : model;
}

/* Warm up the TLS pool for the configured LLM endpoint.  No-op when a
 * live connection is already pooled; must be called from the agent task
 * group (see vela_tls_preconnect).  Only the port-443 HTTPS path uses
 * the pool — plain-HTTP endpoints have nothing to preheat. */
int llm_preconnect(void)
{
    /* Snapshot config under lock.  Copy with the SOURCE sizes — the
     * globals are smaller than llm_http_direct's 128-byte locals. */
    char llm_host[64], llm_port[8];
    pthread_mutex_lock(&s_llm_lock);
    memcpy(llm_host, s_llm_host, sizeof(s_llm_host));
    memcpy(llm_port, s_llm_port, sizeof(s_llm_port));
    pthread_mutex_unlock(&s_llm_lock);

    if (llm_host[0] == '\0') {
        return -1;
    }
    if (strcmp(llm_port, "443") != 0) {
        return -1;
    }

    return vela_tls_preconnect(llm_host, llm_port);
}

