847	/* Variant table for "你好" / "openvela" wake words.
848	 * ASR often mis-recognizes the non-dictionary word "openvea",
849	 * so common mis-recognition variants are all accepted. */
850	static const char* const WAKE_WORDS[] = {
851	    "你好",
852	    "openvela",
853	    "openvea",
854	    "openvila",
855	    "openwela",
856	    "openvella",
857	    "欧鹏vela",
