861	/* Normalize ASR text (strip spaces/punctuation, lowercase ASCII)
862	 * then substring-match against the wake-word variant table. */
863	static bool wake_word_match(const char* asr_text)
864	{
865	    char norm[512];
866	    size_t w = 0;
867	    const unsigned char* r = (const unsigned char*)asr_text;
868	
869	    while (*r && w < sizeof(norm) - 1) {
870	        if (*r < 0x80) {
871	            /* Keep only alphanumerics, lowercased; drop space/punct */
872	            if (isalnum(*r)) {
873	                norm[w++] = (char)tolower(*r);
874	            }
875	            r++;
876	            continue;
877	        }
878	        /* Skip common CJK/full-width punctuation (3-byte UTF-8):
879	         * U+3000-3FFF (0xE3 ..), U+FF00-FFEF (0xEF ..),
880	         * U+2000-206F general punct (0xE2 0x80 ..) */
881	        if ((r[0] == 0xE3 || r[0] == 0xEF
882	             || (r[0] == 0xE2 && r[1] == 0x80))
883	            && r[1] != '\0' && r[2] != '\0') {
884	            r += 3;
885	            continue;
886	        }
887	        norm[w++] = (char)*r++;
888	    }
889	    norm[w] = '\0';
890	
891	    for (size_t i = 0; i < sizeof(WAKE_WORDS) / sizeof(WAKE_WORDS[0]); i++) {
892	        if (strstr(norm, WAKE_WORDS[i]) != NULL) {
893	            syslog(LOG_INFO, "[%s] wake word hit: \"%s\" (norm=\"%s\")\n", TAG,
894	                WAKE_WORDS[i], norm);
895	            return true;
896	        }
897	    }
898	    return false;
899	}
