1760	bool voice_channel_is_listening(void)
1761	{
1762	    /* LISTENING = wake-word system fully up and idle.  VOICE_IDLE
1763	     * means the voice system has not started yet (boot) or has been
1764	     * stopped; speaking then would race the initial capture/session
1765	     * setup and corrupt the state machine (observed: wake stuck on
1766	     * "thinking" face after a boot-time async speak). */
1767	    pthread_mutex_lock(&s_voice.lock);
1768	    bool listening = (s_voice.state == VOICE_LISTENING);
1769	    pthread_mutex_unlock(&s_voice.lock);
1770	    return listening;
1771	}
