137	 * 2x-speed / distorted, so build a temp stereo copy (L=R) and return its
138	 * path; otherwise return the source path unchanged.
139	 * Returns the channel count that will actually play (1 or 2), or -1 on a
140	 * hard error that still leaves `dst` as a playable copy of `src`. */
141	
142	#define STEREO_TMP_PATH "/tmp/emotion_stereo.wav"
143	
144	static int wav_ensure_stereo(const char *src, char *dst, size_t dst_sz,
145	                             const struct wav_params *wp)
146	{
147	    if (wp->channels != 1 || wp->bits != 16) {
148	        snprintf(dst, dst_sz, "%s", src);
149	        return (int)wp->channels;
150	    }
151	
152	    FILE *fin = fopen(src, "rb");
153	    if (!fin) {
154	        snprintf(dst, dst_sz, "%s", src);
155	        return 1;
156	    }
157	
158	    fseek(fin, 0, SEEK_END);
159	    long fsz = ftell(fin);
160	    fseek(fin, 0, SEEK_SET);
161	    if (fsz <= (long)wp->data_offset) {
162	        fclose(fin);
163	        snprintf(dst, dst_sz, "%s", src);
164	        return 1;
165	    }
166	
167	    size_t mono_bytes = (size_t)fsz - wp->data_offset;
168	    uint8_t *mono = malloc(mono_bytes);
169	    if (!mono) {
170	        fclose(fin);
171	        snprintf(dst, dst_sz, "%s", src);
172	        return 1;
173	    }
174	
175	    if (fseek(fin, wp->data_offset, SEEK_SET) != 0 ||
176	        fread(mono, 1, mono_bytes, fin) != mono_bytes) {
177	        free(mono);
178	        fclose(fin);
179	        snprintf(dst, dst_sz, "%s", src);
180	        return 1;
181	    }
182	    fclose(fin);
183	
184	    size_t samples = mono_bytes / 2;
185	    size_t stereo_bytes = samples * 4;
186	    uint8_t *stereo = malloc(stereo_bytes);
187	    if (!stereo) {
188	        free(mono);
189	        snprintf(dst, dst_sz, "%s", src);
190	        return 1;
191	    }
192	
193	    const int16_t *m = (const int16_t *)mono;
194	    int16_t *s = (int16_t *)stereo;
195	    for (size_t i = 0; i < samples; i++) {
196	        s[i * 2]     = m[i];
197	        s[i * 2 + 1] = m[i];
198	    }
199	    free(mono);
200	
201	    FILE *fout = fopen(dst, "wb");
202	    if (!fout) {
203	        free(stereo);
204	        snprintf(dst, dst_sz, "%s", src);
205	        return 1;
206	    }
207	
208	    uint32_t data_sz    = (uint32_t)stereo_bytes;
209	    uint32_t riff_sz    = 36 + data_sz;
210	    uint32_t byte_rate  = wp->sample_rate * 4;  /* 2ch × 2 bytes */
211	    uint16_t block_align = 4;
212	
213	    fwrite("RIFF", 1, 4, fout);
214	    fwrite(&riff_sz, 4, 1, fout);
215	    fwrite("WAVE", 1, 4, fout);
216	    fwrite("fmt ", 1, 4, fout);
217	    uint32_t u32 = 16;              fwrite(&u32, 4, 1, fout);
218	    uint16_t u16 = 1;               fwrite(&u16, 2, 1, fout);  /* PCM */
219	    u16 = 2;                        fwrite(&u16, 2, 1, fout);  /* channels */
220	    fwrite(&wp->sample_rate, 4, 1, fout);
221	    fwrite(&byte_rate, 4, 1, fout);
222	    fwrite(&block_align, 2, 1, fout);
223	    u16 = 16;                       fwrite(&u16, 2, 1, fout);  /* bits */
224	    fwrite("data", 1, 4, fout);
225	    fwrite(&data_sz, 4, 1, fout);
226	    fwrite(stereo, 1, stereo_bytes, fout);
227	    fclose(fout);
228	    free(stereo);
229	
230	    syslog(LOG_INFO, "[emotion] mono→stereo converted: %s (%u samples)\n",
231	           src, (unsigned)samples);
232	    return 2;
233	}
