324	static void slide_gesture_sos_main_handler(lv_event_t *e)
325	{
326	    lv_event_code_t code = lv_event_get_code(e);
327	
328	    static lv_point_t start_point = {0};
329	    static bool is_dragging = false;
330	
331	    switch(code) {
332	        case LV_EVENT_PRESSED:
333	            lv_indev_get_point(lv_indev_active(), &start_point);
334	            is_dragging = true;
335	            break;
336	        
337	        case LV_EVENT_RELEASED:
338	            if(is_dragging) {
339	                lv_point_t end_point;
340	                lv_indev_get_point(lv_indev_active(), &end_point);
341	                
342	                int32_t delta_x = end_point.x - start_point.x;
343	                int32_t delta_y = end_point.y - start_point.y;
344	
345	                if(delta_x > 50 && abs(delta_x) > abs(delta_y)) {
346	                    // 右滑：退出当前页面
347	                    if(sos_main_base != NULL) {
348	                        /* 从页面栈中移除 */
349	                        vw_watch_pop_page(sos_main_base);
350	                        lv_obj_del(sos_main_base);
351	                        sos_main_base = NULL;
352	                    }
353	                }
354	            }
355	            is_dragging = false;
356	            break;
357	            
358	        default:
359	            break;
360	    }
361	}
