180	/**
181	 * 统一传感器监控定时器
182	 * 一次读传感器, 同时判断抬腕亮屏(重力旋转)和摔倒(gyro>300)
183	 */
184	static void sensor_monitor_timer_cb(lv_timer_t *timer)
185	{
186	    sensor_imu_data_t data;
187	    if (sensor_data_read(&data) != 0) {
188	        return;
189	    }
190	
191	    float gyro_mag = sqrtf(data.gyro.x * data.gyro.x +
192	                           data.gyro.y * data.gyro.y +
193	                           data.gyro.z * data.gyro.z);
194	
195	    float ax_now = data.accel.x;
196	    float ay_now = data.accel.y;
197	    float az_now = data.accel.z;
198	
199	    float az_prev = g_last_az;
200	    g_last_az = az_now;
201	
202	    float accel_mag = sqrtf(data.accel.x * data.accel.x +
203	                            data.accel.y * data.accel.y +
204	                            data.accel.z * data.accel.z);
205	    (void)accel_mag;
206	
207	    uint64_t now = sensor_get_time_ms();
208	
209	    /* 抬腕亮屏：静止时（陀螺仪幅值小）记录重力参考矢量（佩戴朝向无关），
210	     * 抬腕时陀螺仪冲高→参考被冻结，当前重力与参考的偏差超过阈值即触发。
211	     * 这样既容忍慢速抬腕（中间过渡采样不漏），也适配任意佩戴朝向。 */
212	    if (gyro_mag < GYRO_STILL_THRESH) {
213	        g_ref_ax = ax_now;
214	        g_ref_ay = ay_now;
215	        g_ref_az = az_now;
216	        g_ref_valid = true;
217	    }
218	
219	    float dax = ax_now - g_ref_ax;
220	    float day = ay_now - g_ref_ay;
221	    float daz = az_now - g_ref_az;
222	    float grav_dev = sqrtf(dax * dax + day * day + daz * daz);
223	    bool raised = (g_ref_valid && grav_dev > GRAVITY_ROTATE_DEV);
224	
225	    bool gyro_high = (gyro_mag > FALL_GYRO_THRESH);
226	    float az_change = fabsf(az_now - az_prev);
227	
228	    if (az_change > FALL_AZ_CHANGE_THRESH && g_step_paused) {
229	        g_fall_z_up_time = now;
230	    }
231	
232	    bool in_fall_window = (g_fall_z_up_time > 0 && now - g_fall_z_up_time <= FALL_WINDOW_MS);
233	    bool fall_cond = (in_fall_window && gyro_high && g_step_paused);
234	
235	    if (!g_step_paused) {
236	        sensor_step_counter_update(&data);
237	    }
238	
239	    // printf("[SM] dev=%.2f raised=%d gyro=%.2f fall=%d fw=%d\n",
240	    //        grav_dev, raised, gyro_mag, fall_cond, in_fall_window);
241	
242	    if (raised && g_wrist_raise_enabled && getchange() == 2) {
243	        if (now - g_wrist_raise_last_trigger > WRIST_RAISE_COOLDOWN_MS) {
244	            g_wrist_raise_last_trigger = now;
245	            g_fall_last_trigger = now;
246	            esp32s3_display_on();
247	            setchange(1);
248	            ft3168_display_timeout_setup();
249	            SENSOR_LOG("[WRIST] Screen on");
250	            g_ref_valid = false;  /* 触发后复位参考，待再次静止重建 */
251	        }
252	    }
253	
254	    if (fall_cond) {
255	        if (now - g_fall_last_trigger > FALL_COOLDOWN_MS) {
256	            g_fall_last_trigger = now;
257	            g_wrist_raise_last_trigger = now;
258	            g_fall_z_up_time = 0;
259	        }

254	    if (fall_cond) {
255	        if (now - g_fall_last_trigger > FALL_COOLDOWN_MS) {
256	            g_fall_last_trigger = now;
257	            g_wrist_raise_last_trigger = now;
258	            g_fall_z_up_time = 0;
259	        }
260	    }
261	}
