433	int watch_expression_page_set_face(const char* face_id, int duration_ms)
434	{
435	    if (face_id == NULL || s_expr_gif == NULL || s_expr_count <= 0) {
436	        return -1;
437	    }
438	
439	    /* 查找 face_id 对应的 GIF 索引 */
440	    int gif_index = -1;
441	    for (size_t i = 0; i < FACE_MAP_SIZE; i++) {
442	        if (strcmp(face_id, s_face_map[i].face_id) == 0) {
443	            gif_index = s_face_map[i].gif_index;
444	            break;
445	        }
446	    }
447	
448	    if (gif_index < 0) {
449	        PAGE_LOG("set_face: unknown face_id '%s'", face_id);
450	        return -1;
451	    }
452	
453	    /* 同脸去重：当前已持久显示该表情（无恢复定时器）且本次也是
454	     * 持久请求 → 跳过。否则 GIF 会从第 0 帧重播，用户看到表情
455	     * "切换两次"——跌倒/扶正/电量提醒链路都是双切模式：motion
456	     * 线程（或注入方）立即预设 sick/proud，agent PROACTIVE 分支
457	     * 在 LLM 回合后（约 3-4 秒）再设同一张脸。
458	     * 带时长的请求（duration>0）永不去重：它必须刷新恢复定时器；
459	     * timed→persistent 的同脸请求也不去重：它必须取消定时器。 */
460	    if (gif_index == s_cur_gif_index && s_cur_persistent
461	        && duration_ms == 0) {
462	        PAGE_LOG("set_face: %s already showing, skip restart",
463	                 face_id);
464	        return 0;
465	    }
466	
467	    PAGE_LOG("set_face: %s -> index %d, duration=%dms",
468	             face_id, gif_index, duration_ms);
469	
470	    /* 记录恢复时长（LVGL线程会读取并创建定时器） */
471	    s_restore_duration_ms = duration_ms;
472	    /* 同步去重状态（async 回调消费 s_restore_duration_ms） */
473	    s_cur_gif_index = gif_index;
474	    s_cur_persistent = (duration_ms == 0);
475	
476	    /* 在 LVGL 线程中执行表情切换 + 创建恢复定时器 */
477	    lv_async_call(set_face_async_cb, (void*)(intptr_t)gif_index);
478	
479	    return 0;
480	}
