110	#define EVENT_EXPIRE_MS      60000       /* get_motion_event freshness */
111	
112	/* Proactive prompts — same pattern as the battery reminders in
113	 * watch_pages.c: the LLM composes the spoken line, tools are forbidden
114	 * (the face is applied by the agent_loop PROACTIVE branch). */
115	#define FALL_PROMPT_INJECT \
116	    "【系统】我摔倒了，起不来啦。请主动向主人求助，" \
117	    "让主人把我扶起来，用一句话表达，语气自然，不要调用任何工具。"
118	#define UPRIGHT_PROMPT_INJECT \
119	    "【系统】主人刚把我扶起来了。请用一句话表达感谢和开心，" \
120	    "语气自然，不要调用任何工具。"
