122	static const char *TAG = "motion";
123	
124	/* Protection state flag (fall_protection_feedback tool) — gates the
125	 * proactive prompts only; detection and get_motion_event keep working
126	 * so the LLM can re-enable it.  Defined before the monitor thread
127	 * because motion_inject() checks it. */
128	static volatile bool s_fall_protected = true;
129	
130	#if MOTION_IMU_AVAILABLE
131	
132	typedef enum {
133	    MOTION_MONITORING = 0,
134	    MOTION_FALLEN,
135	    MOTION_FALLEN_TIMEOUT,
136	} motion_state_t;
137	
138	/* Last event — written by the monitor thread, read by the agent loop
139	 * thread from tool_get_motion_event_execute. */
140	typedef struct {
141	    char     event[12];      /* "fall" / "upright" */
142	    char     direction[12];  /* left/right/forward/backward/unknown/none */
143	    float    angle_deg;
144	    uint32_t time_ms;        /* CLOCK_MONOTONIC ms */
145	} motion_event_t;
146	
147	static volatile bool s_motion_running = false;
148	static motion_state_t s_state = MOTION_MONITORING;
149	
150	/* Fixed upright reference & gyro zero-rate offset (v5: constants —
151	 * the boot calibration that used to fill these is gone). */
152	static const float s_base_x = REF_BASE_X, s_base_y = REF_BASE_Y,
153	                   s_base_z = REF_BASE_Z;
154	static const float s_gyro_ox = REF_GYRO_OX, s_gyro_oy = REF_GYRO_OY,
155	                   s_gyro_oz = REF_GYRO_OZ;
156	
157	/* Shared event slot */
158	static pthread_mutex_t s_event_lock = PTHREAD_MUTEX_INITIALIZER;
159	static motion_event_t s_last_event;
160	
161	static uint32_t now_ms(void)
162	{
163	    struct timespec ts;
164	    clock_gettime(CLOCK_MONOTONIC, &ts);
165	    return (uint32_t)(ts.tv_sec * 1000L + ts.tv_nsec / 1000000L);
166	}
167	
168	/* Gate + inject, reusing the battery-reminder pattern: only from the
169	 * LISTENING state, never muted, and keep the fixed face during TTS.
170	 * Returns true when the prompt was queued. */
171	static bool motion_inject(const char *prompt)
172	{
173	    if (!s_fall_protected)
174	        return false;
175	    if (!voice_channel_is_listening())
176	        return false;
177	    if (voice_channel_is_mic_muted())
178	        return false;
179	    voice_channel_suppress_speaking_face(true);
180	    return voice_channel_inject_prompt(prompt) == OK;
181	}
182	
183	static void motion_record_event(const char *event, const char *dir,
184	                                float angle)
185	{
186	    pthread_mutex_lock(&s_event_lock);
187	    strncpy(s_last_event.event, event, sizeof(s_last_event.event) - 1);
188	    s_last_event.event[sizeof(s_last_event.event) - 1] = '\0';
189	    strncpy(s_last_event.direction, dir, sizeof(s_last_event.direction) - 1);
190	    s_last_event.direction[sizeof(s_last_event.direction) - 1] = '\0';
191	    s_last_event.angle_deg = angle;
192	    s_last_event.time_ms = now_ms();
193	    pthread_mutex_unlock(&s_event_lock);
194	}
