196	/* Direction from the resting gravity vector (design doc 8.3):
197	 * |x| > 0.6 -> side fall, |z| > 0.8 -> front/back fall. */
198	static const char *motion_direction(float ax, float az)
199	{
200	    if (fabsf(ax) > 0.6f)
201	        return ax > 0.0f ? "left" : "right";
202	    if (fabsf(az) > 0.8f)
203	        return az > 0.0f ? "forward" : "backward";
204	    return "unknown";
205	}
