207	/* ── Monitor thread ─────────────────────────────────────────────── */
208	
209	static void *motion_monitor_thread(void *arg)
210	{
211	    (void)arg;
212	
213	    struct pollfd fds[2];
214	    const struct orb_metadata *meta_acc = ORB_ID(sensor_accel);
215	    const struct orb_metadata *meta_gyr = ORB_ID(sensor_gyro);
216	    struct sensor_accel acc;
217	    struct sensor_gyro gyr;
218	
219	    /* Subscribe (retry: the sensor driver registers during boot) */
220	    int fd_acc = -1, fd_gyr = -1;
221	    for (int attempt = 0; attempt < 5 && s_motion_running; attempt++) {
222	        if (fd_acc < 0) {
223	            fd_acc = orb_subscribe_multi(meta_acc, 0);
224	            if (fd_acc >= 0)
225	                orb_set_interval(fd_acc, MOTION_SAMPLE_INTERVAL_US);
226	        }
227	        if (fd_gyr < 0) {
228	            fd_gyr = orb_subscribe_multi(meta_gyr, 0);
229	            if (fd_gyr >= 0)
230	                orb_set_interval(fd_gyr, MOTION_SAMPLE_INTERVAL_US);
231	        }
232	        if (fd_acc >= 0 && fd_gyr >= 0)
233	            break;
234	        syslog(LOG_WARNING,
235	            "[%s] sensor subscribe failed (accel=%d gyro=%d), retry %d\n",
236	            TAG, fd_acc, fd_gyr, attempt + 1);
237	        sleep(1);
238	    }
239	    if (fd_acc < 0 || fd_gyr < 0) {
240	        syslog(LOG_ERR, "[%s] IMU not available, monitor exits\n", TAG);
241	        if (fd_acc >= 0) orb_unsubscribe(fd_acc);
242	        if (fd_gyr >= 0) orb_unsubscribe(fd_gyr);
243	        s_motion_running = false;
244	        return NULL;
245	    }
246	
247	    fds[0].fd = fd_acc;
248	    fds[0].events = POLLIN;
249	    fds[1].fd = fd_gyr;
250	    fds[1].events = POLLIN;
251	
252	    /* Frame-derived quantities */
253	    bool have_acc = false, have_gyr = false;
254	    float theta = 0.0f, mag = 0.0f;
255	    bool quiet = false;
256	
257	    /* State-machine locals (all CLOCK_MONOTONIC ms, 0 = not started) */
258	    uint32_t fall_start_ms = 0;     /* MONITORING: theta>60 since */
259	    uint32_t fallen_at_ms = 0;      /* FALLEN entry time */
260	    uint32_t recover_start_ms = 0;  /* FALLEN: theta<30 since */
261	    uint32_t next_inject_ms = 0;    /* FALLEN: next help-prompt retry */
262	    uint32_t next_status_ms = 0;    /* FALLEN/timeout: next telemetry line */
263	    bool fall_prompt_sent = false;
264	
265	    syslog(LOG_INFO, "[%s] monitor started (fixed upright reference)\n", TAG);
266	
267	    /* Stream watchdog.  A poll timeout leaves the state machine frozen
268	     * mid-switch — the 30s FALLEN timeout keeps expiring silently and
269	     * re-arm never evaluates.  First field test went silent for 2+
270	     * minutes with no way to tell "sensor stream died" (driver worker
271	     * stalled / HPWORK blocked) from "thread died" from "posture
272	     * wrong".  The stall/recover pair below splits the first two from
273	     * the rest; the per-state telemetry lines split the third. */
274	    int starve_polls = 0;
275	    uint32_t starve_since_ms = 0;
276	
277	    while (s_motion_running) {
278	        int rc = poll(fds, 2, MOTION_POLL_TIMEOUT_MS);
279	        if (rc < 0) {
280	            if (errno == EINTR)
281	                continue;
282	            break;
283	        }
284	        if (rc == 0) {
285	            if (starve_polls == 0)
286	                starve_since_ms = now_ms();
287	            if (++starve_polls == 6)   /* ~3s without a single frame */
288	                syslog(LOG_WARNING,
289	                    "[%s] sensor stream stalled (state=%d, %.1fs)\n",
290	                    TAG, (int)s_state,
291	                    (now_ms() - starve_since_ms) / 1000.0f);
292	            continue;
293	        }
294	
295	        bool got_frame = false;
296	        if (fds[0].revents & POLLIN) {
297	            have_acc = orb_copy(meta_acc, fd_acc, &acc) == OK;
298	            got_frame = true;
299	        }
300	        if (fds[1].revents & POLLIN) {
301	            have_gyr = orb_copy(meta_gyr, fd_gyr, &gyr) == OK;
302	            got_frame = true;
303	        }
304	        if (got_frame) {
305	            if (starve_polls >= 6)
306	                syslog(LOG_WARNING,
307	                    "[%s] sensor stream recovered after %.1fs\n",
308	                    TAG, (now_ms() - starve_since_ms) / 1000.0f);
309	            starve_polls = 0;
310	        }
311	        if (!have_acc || !have_gyr)
312	            continue;
313	
314	        uint32_t now = now_ms();
315	
316	        mag = sqrtf(acc.x * acc.x + acc.y * acc.y + acc.z * acc.z);
317	        float wx = gyr.x - s_gyro_ox;
318	        float wy = gyr.y - s_gyro_oy;
319	        float wz = gyr.z - s_gyro_oz;
320	        float omega = sqrtf(wx * wx + wy * wy + wz * wz);
321	        quiet = (mag >= QUIET_ACCEL_MIN && mag <= QUIET_ACCEL_MAX &&
322	                 omega < QUIET_GYRO_RPS);
323	
324	        /* Tilt angle vs. baseline (|base| == 1) */
325	        float dot = acc.x * s_base_x + acc.y * s_base_y + acc.z * s_base_z;
326	        float cosv = mag > 0.0f ? dot / mag : 1.0f;
327	        if (cosv > 1.0f) cosv = 1.0f;
328	        if (cosv < -1.0f) cosv = -1.0f;
329	        theta = acosf(cosv) * (180.0f / 3.14159265f);
330	
331	        switch (s_state) {
332	        case MOTION_MONITORING:
333	            if (quiet && theta > FALL_ANGLE_DEG) {
334	                if (fall_start_ms == 0) {
335	                    fall_start_ms = now;
336	                } else if (now - fall_start_ms >= FALL_CONFIRM_MS) {
337	                    fallen_at_ms = now;
338	                    const char *dir = motion_direction(acc.x, acc.z);
339	                    motion_record_event("fall", dir, theta);
340	                    syslog(LOG_WARNING,
341	                        "[%s] FALL %s theta=%.0f mag=%.2f omega=%.1f\n",
342	                        TAG, dir, theta, mag, omega);
343	                    /* Distress face NOW, not after the LLM round trip
344	                     * (~5-10s later): the user must see the toy react
345	                     * the moment it tips over.  The agent's PROACTIVE
346	                     * branch re-applies the same face before TTS
347	                     * (idempotent), and voice restores "listening"
348	                     * after playback. */
349	#ifdef CONFIG_EXAMPLES_CONTEST2026_WATCH_BOOT
350	                    watch_expression_page_set_face("sick", 0);
351	#endif
352	                    fall_prompt_sent = false;
353	                    next_inject_ms = now;   /* try immediately */
354	                    recover_start_ms = 0;
355	                    fall_start_ms = 0;
356	                    next_status_ms = now + 5000;
357	                    s_state = MOTION_FALLEN;
358	                }
359	            } else {
360	                fall_start_ms = 0;
361	            }
362	            break;
363	
364	        case MOTION_FALLEN:
365	            /* Telemetry while waiting to be righted: separates a
366	             * wrong-posture upright (theta stays >= 30) from a
367	             * never-quiet one (held in a moving hand).  First field
368	             * test showed upright recognition failing with zero
369	             * diagnostics — these lines pin down the posture. */
370	            if ((int32_t)(now - next_status_ms) >= 0) {
371	                syslog(LOG_INFO,
372	                    "[%s] recovery wait: a=(%.2f,%.2f,%.2f) theta=%.0f "
373	                    "quiet=%d mag=%.2f omega=%.1f\n",
374	                    TAG, acc.x, acc.y, acc.z, theta, quiet, mag, omega);
375	                next_status_ms = now + 5000;
376	            }
377	
378	            /* Help prompt — retried while voice is not ready. */
379	            if (!fall_prompt_sent && (int32_t)(now - next_inject_ms) >= 0) {
380	                if (motion_inject(FALL_PROMPT_INJECT)) {
381	                    fall_prompt_sent = true;
382	                    syslog(LOG_INFO, "[%s] fall prompt injected\n", TAG);
383	                } else {
384	                    next_inject_ms = now + INJECT_RETRY_MS;
385	                }
386	            }
387	
388	            /* Pick-up detection */
389	            if (quiet && theta < RECOVER_ANGLE_DEG) {
390	                if (recover_start_ms == 0) {
391	                    recover_start_ms = now;
392	                } else if (now - recover_start_ms >= RECOVER_CONFIRM_MS) {
393	                    motion_record_event("upright", "none", theta);
394	                    syslog(LOG_INFO, "[%s] UPRIGHT theta=%.0f\n", TAG, theta);
395	                    /* Happy face NOW — mirrors the FALL branch; also
396	                     * covers the timeout path where no thanks turn
397	                     * runs (fall_prompt_sent == false) and nothing
398	                     * else would clear the sick face. */
399	#ifdef CONFIG_EXAMPLES_CONTEST2026_WATCH_BOOT
400	                    watch_expression_page_set_face("proud", 0);
401	#endif
402	                    /* Thank the user only if the help line was spoken. */
403	                    if (fall_prompt_sent) {
404	                        if (!motion_inject(UPRIGHT_PROMPT_INJECT))
405	                            syslog(LOG_WARNING,
406	                                "[%s] upright prompt dropped (voice busy)\n", TAG);
407	                    }
408	                    recover_start_ms = 0;
409	                    s_state = MOTION_MONITORING;
410	                }
411	            } else {
412	                recover_start_ms = 0;
413	            }
414	
415	            /* Nobody picked it up — go silent, wait for a real pick-up. */
416	            if (now - fallen_at_ms >= FALLEN_TIMEOUT_MS) {
417	                syslog(LOG_INFO,
418	                    "[%s] fallen timeout after %lus, going silent\n",
419	                    TAG, (unsigned long)((now - fallen_at_ms) / 1000));
420	                next_status_ms = now + 10000;
421	                s_state = MOTION_FALLEN_TIMEOUT;
422	            }
423	            break;
424	
425	        case MOTION_FALLEN_TIMEOUT:
426	            /* Telemetry: shows why re-arm hasn't fired (posture still
427	             * >= 30 deg off the fixed reference, or never quiet). */
428	            if ((int32_t)(now - next_status_ms) >= 0) {
429	                syslog(LOG_INFO,
430	                    "[%s] re-arm wait: a=(%.2f,%.2f,%.2f) theta=%.0f "
431	                    "quiet=%d mag=%.2f omega=%.1f\n",
432	                    TAG, acc.x, acc.y, acc.z, theta, quiet, mag, omega);
433	                next_status_ms = now + 10000;
434	            }
435	
436	            /* Re-arm only after the toy was really picked upright. */
437	            if (quiet && theta < RECOVER_ANGLE_DEG) {
438	                syslog(LOG_INFO, "[%s] re-armed\n", TAG);
439	                /* Timeout path: the UPRIGHT branch above never ran, so
440	                 * restore the listening face that the FALL branch took
441	                 * away — otherwise the toy stays "sick" forever. */
442	#ifdef CONFIG_EXAMPLES_CONTEST2026_WATCH_BOOT
443	                watch_expression_page_set_face("listening", 0);
444	#endif
445	                s_state = MOTION_MONITORING;
446	            }
447	            break;
448	
449	        default:
450	            s_state = MOTION_MONITORING;
451	            break;
452	        }
453	    }
454	
455	    orb_unsubscribe(fd_acc);
456	    orb_unsubscribe(fd_gyr);
457	    syslog(LOG_INFO, "[%s] monitor stopped (state=%d)\n", TAG, (int)s_state);
458	    return NULL;
459	}
