464	
465	int tool_get_motion_event_execute(const char *input_json, char *output, size_t output_size)
466	{
467	    (void)input_json;
468	
469	#if MOTION_IMU_AVAILABLE
470	    bool valid = false;
471	    char event[12] = "";
472	    char direction[12] = "";
473	    float angle = 0.0f;
474	
475	    pthread_mutex_lock(&s_event_lock);
476	    if (s_last_event.time_ms != 0 &&
477	        now_ms() - s_last_event.time_ms < EVENT_EXPIRE_MS) {
478	        valid = true;
479	        strncpy(event, s_last_event.event, sizeof(event) - 1);
480	        strncpy(direction, s_last_event.direction, sizeof(direction) - 1);
481	        angle = s_last_event.angle_deg;
482	    }
483	    pthread_mutex_unlock(&s_event_lock);
484	
485	    if (valid) {
486	        snprintf(output, output_size,
487	            "{\"event\":\"%s\",\"direction\":\"%s\",\"angle\":%.0f}",
488	            event, direction, angle);
489	        return OK;
490	    }
491	#endif
492	
