498	/* ── fall_protection_feedback ──────────────────────────────────────── */
499	
500	int tool_fall_protection_feedback_execute(const char *input_json,
501	                                           char *output, size_t output_size)
502	{
503	    cJSON *root = cJSON_Parse(input_json);
504	    if (!root) {
505	        snprintf(output, output_size, "{\"error\":\"invalid json\"}");
506	        return ERROR;
507	    }
508	
509	    cJSON *action = cJSON_GetObjectItem(root, "action");
510	    if (!cJSON_IsString(action) || !action->valuestring[0]) {
511	        snprintf(output, output_size, "{\"error\":\"action required\"}");
512	        cJSON_Delete(root);
513	        return ERROR;
514	    }
515	
516	    const char *act = action->valuestring;
517	    cJSON_Delete(root);
518	
519	    if (strcmp(act, "enable") == 0) {
520	        s_fall_protected = true;
521	        syslog(LOG_WARNING, "[emotion] fall protection enabled\n");
522	        snprintf(output, output_size,
523	            "{\"status\":\"ok\",\"action\":\"enable\",\"protected\":true}");
524	        return OK;
525	    }
526	
527	    if (strcmp(act, "disable") == 0) {
528	        s_fall_protected = false;
529	        syslog(LOG_INFO, "[emotion] fall protection disabled\n");
530	        snprintf(output, output_size,
531	            "{\"status\":\"ok\",\"action\":\"disable\",\"protected\":false}");
532	        return OK;
533	    }
534	
535	    snprintf(output, output_size, "{\"error\":\"invalid action, must be enable or disable\"}");
536	    return ERROR;
537	}
