541	int tool_emotion_motion_start(void)
542	{
543	#if MOTION_IMU_AVAILABLE
544	    if (s_motion_running) {
545	        syslog(LOG_WARNING, "[%s] monitor already running\n", TAG);
546	        return OK;
547	    }
548	
549	    /* Fresh state for a re-launched agent (runtime UI-mode switch). */
550	    s_state = MOTION_MONITORING;
551	    memset(&s_last_event, 0, sizeof(s_last_event));
552	    s_fall_protected = true;
553	
554	    s_motion_running = true;
555	    if (agent_task_create(motion_monitor_thread, "motion_mon",
556	                          MOTION_THREAD_STACK, NULL,
557	                          MOTION_THREAD_PRIO) != OK) {
558	        s_motion_running = false;
559	        syslog(LOG_ERR, "[%s] failed to create monitor thread\n", TAG);
560	        return ERROR;
561	    }
562	    return OK;
563	#else
564	    syslog(LOG_WARNING, "[%s] IMU not available, monitor not started\n", TAG);
565	    return ERROR;
566	#endif
567	}
