1773	int voice_channel_inject_prompt(const char* text)
1774	{
1775	    if (!text || text[0] == '\0') {
1776	        return -EINVAL;
1777	    }
1778	
1779	    /* strdup before taking the lock — no malloc under mutex. */
1780	    char* fresh = strdup(text);
1781	    if (!fresh) {
1782	        return -ENOMEM;
1783	    }
1784	
1785	    pthread_mutex_lock(&s_voice.lock);
1786	    char* old = s_voice.pending_prompt;
1787	    s_voice.pending_prompt = fresh;
1788	    pthread_mutex_unlock(&s_voice.lock);
1789	
1790	    /* A newer prompt replaces a not-yet-consumed one. */
1791	    free(old);
1792	
1793	    syslog(LOG_INFO, "[%s] proactive prompt queued: %.40s\n",
1794	        TAG, text);
1795	    return 0;
1796	}
