1812	        pthread_mutex_unlock(&s_voice.lock);
1813	        return -EINVAL;
1814	    }
1815	
1816	    syslog(LOG_INFO, "[%s] stopping conversation (state=%d)\n",
1817	        TAG, s_voice.state);
1818	
1819	    s_voice.conv_running = false;
1820	    s_voice.state = VOICE_IDLE;
1821	
1822	    /* Abort TTS if active */
1823	    s_voice.tts_abort = 1;
1824	    if (s_voice.tts_pb) {
1825	        audio_playback_stop(s_voice.tts_pb);
1826	    }
