1121	int volc_tts_ws_synthesize_stream(const char* text, volc_tts_chunk_cb cb,
1122	    void* user_data)
1123	{
1124	    if (!text || !cb) {
1125	        return -EINVAL;
1126	    }
1127	
1128	    syslog(LOG_INFO, "[%s] synthesize: text=\"%s\" (%zu bytes)\n",
1129	        TAG, text, strlen(text));
1130	
1131	    tts_ws_init();
1132	
1133	    if (s_appid[0] == '\0' || s_token[0] == '\0') {
1134	        syslog(LOG_ERR, "[%s] credentials not configured\n", TAG);
1135	        return -ENOENT;
1136	    }
1137	
1138	    /* Use pre-opened connection if available and not stale */
1139	    tts_tls_ctx_t* ctx = NULL;
1140	    tts_tls_ctx_t* stale = NULL;
1141	    bool used_preopen = false;
