169	            }
170	
171	            if (pr == 0) {
172	                syslog(LOG_ERR, "[%s] connect %s timeout after %dms\n",
173	                    TAG, host, TTS_CONNECT_TIMEOUT_MS);
174	            } else {
175	                syslog(LOG_ERR, "[%s] connect %s: SO_ERROR=%d\n",
176	                    TAG, host, soerr ? soerr : errno);
177	            }
