274	        if (ret != MBEDTLS_ERR_SSL_WANT_READ && ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
275	            syslog(LOG_ERR, "[%s] handshake: -0x%04x\n", TAG, -ret);
276	            ret = -EIO;
277	            goto fail;
278	        }
279	
280	        /* WANT_READ/WANT_WRITE here usually means the 10s socket
281	         * timeout fired mid-handshake.  Retry a little (transient
282	         * stall), but never forever — a peer that parks the handshake
283	         * would otherwise spin this loop indefinitely. */
284	        {
285	            struct timespec hs_t1;
286	
287	            clock_gettime(CLOCK_MONOTONIC, &hs_t1);
288	            if (hs_t1.tv_sec - hs_t0.tv_sec >= 15) {
289	                syslog(LOG_ERR, "[%s] handshake stalled >15s, giving up\n",
290	                    TAG);
291	                ret = -ETIMEDOUT;
292	                goto fail;
293	            }
294	        }
295	    }
296	
297	    syslog(LOG_INFO, "[%s] TLS connected (fd=%d)\n", TAG, ctx->net.fd);
298	    return 0;
299	
300	fail:
301	    tts_tls_free(ctx);
302	    return ret;
303	}
304	
305	static void tts_tls_free(tts_tls_ctx_t* ctx)
306	{
307	    mbedtls_ssl_close_notify(&ctx->ssl);
308	    mbedtls_net_free(&ctx->net);
309	    mbedtls_ssl_free(&ctx->ssl);
310	    mbedtls_ssl_config_free(&ctx->cfg);
311	    mbedtls_ctr_drbg_free(&ctx->ctr_drbg);
312	}
313	
314	/* ── TLS I/O helpers ─────────────────────────────────────────── */
315	
316	static int tls_write_all(tts_tls_ctx_t* ctx, const unsigned char* buf,
317	    size_t len)
318	{
319	    size_t written = 0;
320	    struct timespec t0;
321	
322	    clock_gettime(CLOCK_MONOTONIC, &t0);
323	
324	    while (written < len) {
325	        int ret;
326	
327	        errno = 0;
328	        ret = mbedtls_ssl_write(&ctx->ssl, buf + written, len - written);
329	
330	        if (ret > 0) {
331	            written += (size_t)ret;
332	        } else if (ret == MBEDTLS_ERR_SSL_WANT_WRITE
333	            || ret == MBEDTLS_ERR_SSL_WANT_READ) {
334	            /* Blocking socket + SO_SNDTIMEO: WANT_WRITE means the send
335	             * buffer stayed full until the timeout fired.  Bound the
336	             * total retry budget instead of spinning forever.
337	             * WANT_READ can also surface here (renegotiation) and must
338	             * be retried, not treated as fatal. */
339	            struct timespec t1;
340	
341	            clock_gettime(CLOCK_MONOTONIC, &t1);
342	            if (t1.tv_sec - t0.tv_sec >= 6) {
343	                syslog(LOG_ERR, "[%s] ssl_write stalled >6s, giving up "
344	                    "(%zu/%zu bytes)\n", TAG, written, len);
345	                return -ETIMEDOUT;
346	            }
347	        } else {
348	            /* Keep the raw mbedtls code + errno: -0x004E =
349	             * NET_SEND_FAILED, and errno tells apart peer RST
350	             * (ECONNRESET=104) from local IOB exhaustion (ENOMEM=12)
351	             * and closed/stolen fd (EBADF=9). */
352	            syslog(LOG_ERR, "[%s] ssl_write: -0x%04x errno=%d "
353	                "(%zu/%zu bytes)\n",
354	                TAG, (unsigned)-ret, errno, written, len);
355	            return -EIO;
356	        }
357	    }
358	
359	    return 0;
360	}
361	
362	static int tls_read_all(tts_tls_ctx_t* ctx, unsigned char* buf, size_t len)
363	{
364	    size_t got = 0;
365	
366	    while (got < len) {
367	        int ret;
368	
369	        errno = 0;
370	        ret = mbedtls_ssl_read(&ctx->ssl, buf + got, len - got);
371	
372	        if (ret > 0) {
373	            got += (size_t)ret;
374	        } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
375	            return -ECONNRESET;
376	        } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
377	            /* Distinguish SO_RCVTIMEO timeout from real I/O errors.
378	             * When the socket recv timeout fires, recv() returns -1
379	             * with errno EAGAIN/EWOULDBLOCK, and mbedtls maps that
380	             * to MBEDTLS_ERR_NET_RECV_FAILED (-0x004C).  Return a
381	             * distinct code so callers can treat timeout as normal
382	             * end-of-stream without masking real connection failures. */
383	            if (ret == -0x004C && (errno == EAGAIN || errno == EWOULDBLOCK
384	                                   || errno == ETIMEDOUT)) {
385	                return -ETIMEDOUT;
386	            }
387	            /* Keep the raw mbedtls code + errno: -0x004C =
388	             * NET_RECV_FAILED (errno 104 = peer RST, 9 = bad fd),
389	             * -0x7780/-0x7900 = TLS fatal alert, -0x7200 = bad record. */
390	            syslog(LOG_ERR, "[%s] ssl_read: -0x%04x errno=%d "
391	                "(%zu/%zu bytes)\n",
392	                TAG, (unsigned)-ret, errno, got, len);
393	            return -EIO;
394	        }
395	    }
396	
397	    return 0;
398	}
399	
400	/* ── WebSocket upgrade ───────────────────────────────────────── */
401	
402	static int ws_upgrade(tts_tls_ctx_t* ctx, const char* host, const char* path,
403	    const char* token)
404	{
405	    unsigned char key_raw[16];
406	    unsigned char key_b64[32];
407	    size_t key_b64_len;
408	
409	    tts_entropy_func(NULL, key_raw, sizeof(key_raw));
410	    mbedtls_base64_encode(key_b64, sizeof(key_b64), &key_b64_len, key_raw,
411	        sizeof(key_raw));
412	
413	    char req[768];
414	    int n = snprintf(req, sizeof(req),
415	        "GET %s HTTP/1.1\r\n"
416	        "Host: %s\r\n"
417	        "Upgrade: websocket\r\n"
418	        "Connection: Upgrade\r\n"
419	        "Sec-WebSocket-Key: %.*s\r\n"
420	        "Sec-WebSocket-Version: 13\r\n"
421	        "Authorization: Bearer;%s\r\n"
422	        "\r\n",
423	        path, host, (int)key_b64_len, key_b64, token);
424	
425	    if (n <= 0 || n >= (int)sizeof(req)) {
426	        return -EOVERFLOW;
427	    }
428	
429	    int ret = tls_write_all(ctx, (const unsigned char*)req, (size_t)n);
430	
431	    if (ret != 0) {
432	        return ret;
433	    }
434	
435	    char resp[1024];
436	    size_t rlen = 0;
437	
438	    while (rlen < sizeof(resp) - 1) {
439	        errno = 0;
440	        int r = mbedtls_ssl_read(&ctx->ssl, (unsigned char*)resp + rlen,
441	            sizeof(resp) - 1 - rlen);
442	
443	        if (r > 0) {
444	            rlen += (size_t)r;
445	            resp[rlen] = '\0';
446	            if (strstr(resp, "\r\n\r\n")) {
447	                break;
448	            }
449	        } else if (r == 0 || r == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
450	            syslog(LOG_ERR, "[%s] WS upgrade: peer closed (r=%d)\n", TAG, r);
451	            return -ECONNRESET;
452	        } else if (r != MBEDTLS_ERR_SSL_WANT_READ) {
453	            syslog(LOG_ERR, "[%s] WS upgrade read: -0x%04x errno=%d\n",
454	                TAG, (unsigned)-r, errno);
455	            return -EIO;
456	        }
457	    }
458	
459	    int status = 0;
460	
461	    if (sscanf(resp, "HTTP/1.1 %d", &status) != 1 || status != 101) {
462	        syslog(LOG_ERR, "[%s] WS upgrade failed: HTTP %d\n", TAG, status);
463	        return -EPROTO;
464	    }
465	
466	    syslog(LOG_INFO, "[%s] WebSocket upgrade OK\n", TAG);
467	    return 0;
468	}
469

470	/* ── WebSocket frame send (client must mask) ─────────────────── */
471	
472	static int ws_send_binary(tts_tls_ctx_t* ctx, const unsigned char* payload,
473	    size_t plen)
474	{
475	    unsigned char hdr[14];
476	    size_t hdr_len = 0;
477	
478	    hdr[0] = WS_FIN_BIT | WS_OPCODE_BINARY;
479	
480	    if (plen < 126) {
481	        hdr[1] = WS_MASK_BIT | (unsigned char)plen;
482	        hdr_len = 2;
483	    } else if (plen <= 0xFFFF) {
484	        hdr[1] = WS_MASK_BIT | 126;
485	        hdr[2] = (unsigned char)(plen >> 8);
486	        hdr[3] = (unsigned char)(plen & 0xFF);
487	        hdr_len = 4;
488	    } else {
489	        hdr[1] = WS_MASK_BIT | 127;
490	        memset(hdr + 2, 0, 4);
491	        hdr[6] = (unsigned char)((plen >> 24) & 0xFF);
492	        hdr[7] = (unsigned char)((plen >> 16) & 0xFF);
493	        hdr[8] = (unsigned char)((plen >> 8) & 0xFF);
494	        hdr[9] = (unsigned char)(plen & 0xFF);
495	        hdr_len = 10;
496	    }
497	
498	    unsigned char mask[WS_MASK_KEY_LEN];
499	
500	    tts_entropy_func(NULL, mask, WS_MASK_KEY_LEN);
501	    memcpy(hdr + hdr_len, mask, WS_MASK_KEY_LEN);
502	    hdr_len += WS_MASK_KEY_LEN;
503	
504	    int ret = tls_write_all(ctx, hdr, hdr_len);
505	
506	    if (ret != 0) {
507	        return ret;
508	    }
509	
510	    unsigned char chunk[1024];
511	    size_t sent = 0;
512	
513	    while (sent < plen) {
514	        size_t clen = plen - sent;
515	
516	        if (clen > sizeof(chunk)) {
517	            clen = sizeof(chunk);
518	        }
519	
520	        for (size_t i = 0; i < clen; i++) {
521	            chunk[i] = payload[sent + i] ^ mask[(sent + i) % 4];
522	        }
523	
524	        ret = tls_write_all(ctx, chunk, clen);
525	        if (ret != 0) {
526	            return ret;
527	        }
528	
529	        sent += clen;
530	    }
531	
532	    return 0;
533	}
534	
535	/* ── WebSocket PONG (reply to server PING) ───────────────────── */
536	
537	/* An unanswered PING makes the gateway drop the connection, which is a
538	 * prime suspect for pre-opened connections parked while the LLM runs. */
539	static int ws_send_pong(tts_tls_ctx_t* ctx, const unsigned char* payload,
540	    size_t plen)
541	{
542	    unsigned char frame[2 + WS_MASK_KEY_LEN + 125];
543	    unsigned char mask[WS_MASK_KEY_LEN];
544	
545	    if (plen > 125) {
546	        plen = 125; /* WS spec caps control frame payloads */
547	    }
548	
549	    tts_entropy_func(NULL, mask, WS_MASK_KEY_LEN);
550	
551	    frame[0] = WS_FIN_BIT | WS_OPCODE_PONG;
552	    frame[1] = WS_MASK_BIT | (unsigned char)plen;
553	    memcpy(frame + 2, mask, WS_MASK_KEY_LEN);
554	
555	    for (size_t i = 0; i < plen; i++) {
556	        frame[2 + WS_MASK_KEY_LEN + i] = payload[i] ^ mask[i % 4];
557	    }
558	
559	    return tls_write_all(ctx, frame, 2 + WS_MASK_KEY_LEN + plen);
560	}
561	
562	/* ── WebSocket frame recv ────────────────────────────────────── */
563	
564	static int ws_recv_frame(tts_tls_ctx_t* ctx, unsigned char* buf, size_t cap,
565	    size_t* out_len, int* out_opcode)
566	{
567	    unsigned char hdr[2];
568	    int ret = tls_read_all(ctx, hdr, 2);
569	
570	    if (ret != 0) {
571	        return ret;
572	    }
573	
574	    *out_opcode = hdr[0] & 0x0F;
575	    int masked = (hdr[1] & WS_MASK_BIT) != 0;
576	    size_t plen = hdr[1] & 0x7F;
577	
578	    if (plen == 126) {
579	        unsigned char ext[2];
580	
581	        ret = tls_read_all(ctx, ext, 2);
582	        if (ret != 0) {
583	            return ret;
584	        }
585	
586	        plen = ((size_t)ext[0] << 8) | ext[1];
587	    } else if (plen == 127) {
588	        unsigned char ext[8];
589	
590	        ret = tls_read_all(ctx, ext, 8);
591	        if (ret != 0) {
592	            return ret;
593	        }
594	
595	        plen = ((size_t)ext[4] << 24) | ((size_t)ext[5] << 16) | ((size_t)ext[6] << 8) | ext[7];
596	    }
597	
598	    unsigned char mask_key[WS_MASK_KEY_LEN];
599	
600	    if (masked) {
601	        ret = tls_read_all(ctx, mask_key, WS_MASK_KEY_LEN);
602	        if (ret != 0) {
603	            return ret;
604	        }
605	    }
606	
607	    if (plen > cap) {
608	        syslog(LOG_ERR,
609	            "[%s] WS frame too large: %zu (opcode=0x%x masked=%d cap=%zu)\n",
610	            TAG, plen, *out_opcode, masked, cap);
611	        return -EOVERFLOW;
612	    }
613	
614	    if (plen > 0) {
615	        ret = tls_read_all(ctx, buf, plen);
616	        if (ret != 0) {
617	            return ret;
618	        }
619	
620	        if (masked) {
621	            for (size_t i = 0; i < plen; i++) {
622	                buf[i] ^= mask_key[i % 4];
623	            }
624	        }
625	    }
626	
627	    *out_len = plen;
628	    return 0;
629	}
630	
631	/* ── Volcengine frame send ───────────────────────────────────── */
632	
633	static int send_volc_frame(tts_tls_ctx_t* ctx, unsigned char msg_type,
634	    unsigned char serialization,
635	    const unsigned char* payload, size_t plen)
636	{
637	    unsigned char* frame = malloc(VOLC_HDR_SIZE + plen);
638	
639	    if (!frame) {
640	        return -ENOMEM;
641	    }
642	
643	    frame[0] = VOLC_PROTO_VER;
644	    frame[1] = msg_type;
645	    frame[2] = serialization;
646	    frame[3] = 0x00;
647	    frame[4] = (unsigned char)((plen >> 24) & 0xFF);
648	    frame[5] = (unsigned char)((plen >> 16) & 0xFF);
649	    frame[6] = (unsigned char)((plen >> 8) & 0xFF);
650	    frame[7] = (unsigned char)(plen & 0xFF);
651	
652	    if (plen > 0) {
653	        memcpy(frame + VOLC_HDR_SIZE, payload, plen);
654	    }
655	
656	    int ret = ws_send_binary(ctx, frame, VOLC_HDR_SIZE + plen);
657	
658	    free(frame);
659	    return ret;
660	}
