662	/* ── Build and send TTS full_client_request (V1 format) ─────── */
663	
664	static int send_tts_request(tts_tls_ctx_t* ctx, const char* text)
665	{
666	    cJSON* root = cJSON_CreateObject();
667	
668	    if (!root) {
669	        return -ENOMEM;
670	    }
671	
672	    /* app */
673	    cJSON* app = cJSON_AddObjectToObject(root, "app");
674	
675	    cJSON_AddStringToObject(app, "appid", s_appid);
676	    cJSON_AddStringToObject(app, "token", s_token);
677	    cJSON_AddStringToObject(app, "cluster", s_cluster);
678	
679	    /* user */
680	    cJSON* user = cJSON_AddObjectToObject(root, "user");
681	
682	    cJSON_AddStringToObject(user, "uid", "agent");
683	
684	    /* audio */
685	    cJSON* audio = cJSON_AddObjectToObject(root, "audio");
686	
687	    cJSON_AddStringToObject(audio, "voice_type", s_speaker);
688	    cJSON_AddStringToObject(audio, "encoding", "pcm");
689	    cJSON_AddNumberToObject(audio, "sample_rate", AGENT_TTS_WS_SAMPLE_RATE);

690	    cJSON_AddNumberToObject(audio, "speed_ratio", 1.0);
691	    cJSON_AddNumberToObject(audio, "volume_ratio", 2.0);
692	
693	    /* request */
694	    cJSON* req = cJSON_AddObjectToObject(root, "request");
695	
696	    cJSON_AddStringToObject(req, "reqid", "agent-tts");
697	    cJSON_AddStringToObject(req, "text", text);
698	    cJSON_AddStringToObject(req, "text_type", "plain");
699	    cJSON_AddStringToObject(req, "operation", "submit");
700	
701	    char* json_str = cJSON_PrintUnformatted(root);
702	
703	    cJSON_Delete(root);
704	
705	    if (!json_str) {
706	        return -ENOMEM;
707	    }
708	
709	    syslog(LOG_INFO, "[%s] TTS request: text=%zu bytes\n",
710	        TAG, strlen(text));
711	
712	    int ret = send_volc_frame(ctx, VOLC_MSG_FULL_REQ, VOLC_SER_JSON,
713	        (const unsigned char*)json_str, strlen(json_str));
714	    free(json_str);
715	    return ret;
716	}
717	
718	/* ── Receive audio responses ─────────────────────────────────── */
719	
720	static int recv_tts_audio(tts_tls_ctx_t* ctx, volc_tts_chunk_cb cb,
721	    void* user_data)
722	{
723	    unsigned char* buf = malloc(WS_BUF_SIZE);
724	
725	    if (!buf) {
726	        return -ENOMEM;
727	    }
728	
729	    /* Recv timeout strategy:
730	     * - First chunk: keep the handshake timeout (10s) since TTS synthesis
731	     *   latency varies with text length and server load (200ms–2s typical).
732	     * - After first chunk: tighten to 500ms per recv.  To tolerate
733	     *   transient network stalls without silently truncating audio,
734	     *   allow up to 4 consecutive timeouts (~2s total) before
735	     *   declaring end-of-stream.  A single stall just retries.
736	     *   (Was 2: on a degraded WiFi link the tail of the audio was
737	     *   cut off mid-sentence — "话没说完".)
738	     * The initial 10s timeout was set by tts_tls_connect(), so we only
739	     * need to tighten it after the first audio chunk arrives. */
740	
741	#define TTS_MAX_CONSECUTIVE_TIMEOUTS 4
742	
743	    int chunks = 0;
744	    int consecutive_timeouts = 0;
745	    int err = 0;
746	    int opcode = 0;
747	
748	    while (1) {
749	        size_t flen;
750	        int ret = ws_recv_frame(ctx, buf, WS_BUF_SIZE, &flen, &opcode);
751	
752	        if (ret != 0) {
753	            /* Timeout after audio started: retry up to N times to
754	             * tolerate transient stalls.  Only declare EOF after
755	             * consecutive timeouts exceed the threshold (~2s). */
756	            if (chunks > 0 && ret == -ETIMEDOUT) {
757	                consecutive_timeouts++;
758	                if (consecutive_timeouts < TTS_MAX_CONSECUTIVE_TIMEOUTS) {
759	                    syslog(LOG_DEBUG,
760	                        "[%s] recv timeout %d/%d, retrying\n",
761	                        TAG, consecutive_timeouts,
762	                        TTS_MAX_CONSECUTIVE_TIMEOUTS);
763	                    continue;
764	                }
765	                syslog(LOG_INFO,
766	                    "[%s] recv ended after %d chunks "
767	                    "(%d consecutive timeouts)\n",
768	                    TAG, chunks, consecutive_timeouts);
769	                break;
770	            }
771	
772	            /* Peer close after audio started is normal EOF. */
773	            if (chunks > 0 && ret == -ECONNRESET) {
774	                syslog(LOG_INFO, "[%s] recv ended after %d chunks (rc=%d)\n",
775	                    TAG, chunks, ret);
776	                break;
777	            }
778	
779	            /* Frame overflow after audio started: the oversized frame
780	             * is lost, but keep the audio already received.  Treat as
781	             * graceful EOF so the caller gets is_last=1. */
782	            if (chunks > 0 && ret == -EOVERFLOW) {
783	                syslog(LOG_INFO,
784	                    "[%s] recv ended after %d chunks (overflow, keeping audio)\n",
785	                    TAG, chunks);
786	                break;
787	            }
788	
789	            syslog(LOG_ERR, "[%s] recv error before any audio: %d (opcode=0x%x)\n",
790	                TAG, ret, opcode);
791	            err = ret;
792	            break;
793	        }
794	
795	        /* Any successful frame resets the timeout counter. */
796	        consecutive_timeouts = 0;
797	
798	        if (opcode == WS_OPCODE_CLOSE) {
799	            syslog(LOG_INFO, "[%s] server closed WS\n", TAG);
800	            break;
801	        }
802	
803	        if (opcode == WS_OPCODE_PING) {
804	            syslog(LOG_INFO, "[%s] server PING (%zu bytes), replying PONG\n",
805	                TAG, flen);
806	            ws_send_pong(ctx, buf, flen);
807	            continue;
808	        }
809	
810	        if (opcode == WS_OPCODE_PONG) {
811	            continue;
812	        }
813	
814	        if (flen < 4) {
815	            syslog(LOG_DEBUG,
816	                "[%s] short WS frame: opcode=0x%x len=%zu\n",
817	                TAG, opcode, flen);
818	            continue;
819	        }
820	
821	        unsigned char msg_type = buf[1] & 0xF0;
822	        unsigned char msg_flags = buf[1] & 0x0F;
823	        size_t volc_hdr_len = (size_t)(buf[0] & 0x0F) * 4;
824	
825	
826	        if (volc_hdr_len < 4 || flen < volc_hdr_len) {
827	            syslog(LOG_DEBUG,
828	                "[%s] non-volc frame: opcode=0x%x len=%zu volc_hdr_len=%zu "
829	                "msg_type=0x%x\n",
830	                TAG, opcode, flen, volc_hdr_len, msg_type);
831	            continue;
832	        }
833	
834	        /* Error response */
835	        if (msg_type == VOLC_MSG_ERROR) {
836	            uint32_t code = 0;
837	
838	            if (flen >= volc_hdr_len + 4) {
839	                code = ((uint32_t)buf[volc_hdr_len] << 24) | ((uint32_t)buf[volc_hdr_len + 1] << 16) | ((uint32_t)buf[volc_hdr_len + 2] << 8) | (uint32_t)buf[volc_hdr_len + 3];
840	            }
841	
842	            syslog(LOG_ERR, "[%s] server error: %lu\n", TAG, (unsigned long)code);
843	            err = -EIO;
844	            break;
845	        }
846	
847	        /* Frontend response (e.g. duration info) — signals end of audio
848	         * when it arrives after audio chunks have been received. */
849	        if (msg_type == VOLC_MSG_FRONTEND) {
850	            if (chunks > 0) {
851	                break; /* All audio delivered, frontend is the epilogue */
852	            }
853	            continue;
854	        }
855	
856	        /* Audio-only response (0xB) */
857	        if (msg_type == VOLC_MSG_AUDIO_RESP) {
858	            /* flags: 0=ack(no audio), 1+=has audio data */
859	            if (msg_flags == 0) {
860	                continue; /* ACK, no audio data */
861	            }
862	
863	            /* After volc header: 4-byte sequence (signed) + 4-byte payload_size */
864	            size_t audio_off = volc_hdr_len + 8;
865	
866	            if (flen <= audio_off) {
867	                continue;
868	            }
869	
870	            /* Extract sequence as signed 32-bit (big-endian).
871	             * Per Volcengine binary protocol: sequence < 0 means last frame. */
872	            int32_t seq = (int32_t)(
873	                ((uint32_t)buf[volc_hdr_len] << 24) |
874	                ((uint32_t)buf[volc_hdr_len + 1] << 16) |
875	                ((uint32_t)buf[volc_hdr_len + 2] << 8) |
876	                (uint32_t)buf[volc_hdr_len + 3]);
877	
878	            unsigned char* pcm = buf + audio_off;
879	            size_t pcm_len = flen - audio_off;
