884	            /* After first chunk, tighten recv timeout so we detect
885	             * end-of-stream quickly (server may not send close frame). */
886	            if (chunks == 1 && ctx->net.fd >= 0) {
887	                struct timeval tv = { .tv_sec = 0, .tv_usec = 500000 };
