896	            /* sequence < 0 = last audio frame */
897	            if (seq < 0) {
898	                break;
899	            }
900	        }
901	    }
902	
903	    free(buf);
904	
905	    if (chunks > 0 && err == 0) {
906	        cb(NULL, 0, 1, user_data);
907	    }
908	
909	    syslog(LOG_INFO, "[%s] %d audio chunks delivered\n", TAG, chunks);
910	
911	    if (chunks == 0 && err == 0) {
912	        return -EPROTO;
913	    }
914	
915	    return err;
