364	/* Collect all mono PCM chunks into a pre-allocated RAM buffer.
365	 * The buffer is sized to leave room for the subsequent in-place
366	 * mono→stereo expansion (hence cap = TTS_BUF_CAP / 2). */
367	typedef struct {
368	    unsigned char* buf;
