370	    size_t len;
371	    int err;
372	} tts_collect_ctx_t;
373	
374	static void tts_collect_cb(const unsigned char* pcm, size_t pcm_len,
375	    int is_last, void* ud)
376	{
377	    tts_collect_ctx_t* ctx = ud;
378	    if (ctx->err) return;
379	    if (pcm && pcm_len > 0) {
380	        if (!s_tts_first_chunk) {
381	            struct timespec now;
382	            clock_gettime(CLOCK_MONOTONIC, &now);
383	            long ms = (now.tv_sec - s_tts_start.tv_sec) * 1000
384	                + (now.tv_nsec - s_tts_start.tv_nsec) / 1000000;
385	            syslog(LOG_INFO, "[%s] TTS first chunk: %ldms\n", TAG, ms);
386	            s_tts_first_chunk = 1;
387	        }
388	        if (ctx->len + pcm_len > ctx->cap) {
389	            syslog(LOG_ERR, "[%s] TTS PCM overflow: %zu+%zu>%zu\n",
390	                TAG, ctx->len, pcm_len, ctx->cap);
391	            ctx->err = -ENOSPC;
392	            return;
393	        }
394	        memcpy(ctx->buf + ctx->len, pcm, pcm_len);
395	        ctx->len += pcm_len;
396	    }
397	    (void)is_last;
398	}
